(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-era-entropy-prune"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-1\">一 · 事故现场：一次被“静默剪掉”的视觉证据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-2\">二 · 它到底解决什么：注意力未校准与分布漂移下的误删</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-3\">三 · 它不解决什么：四条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-4\">四 · 代价账本：每轮重算熵买到了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-5\">五 · 一个具体例子：三轮对话里的预算重设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-6\">六 · 稳定性技巧与失效模式：什么时候它会反过来害你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-7\">七 · 剪枝边界：熵信号在哪些推理栈里会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-8\">八 · 从拼接序列到首次取熵：视觉 token 的入口与注意力读取点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-9\">九 · 熵与整流：把注意力分布折算成可排序的不确定性分数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-10\">十 · top-k 保留与序列重建：压缩后的 KV 布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-11\">十一 · 多轮重算：每轮重设熵预算与前向开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-12\">十二 · 失败模式与部署约束：取不到熵、稀释与过激</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-13\">十三 · 熵的定义与逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-14\">十四 · 整流归一化与打分公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-15\">十五 · 为什么熵优于注意力幅值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-16\">十六 · 多轮预算重算的递推视角</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-17\">十七 · 失败模式对应的实现约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-18\">十八 · 整流项与熵预算的失效边界：从公式到可落地的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-19\">十九 · 边界、失效条件与系统代价：熵剪枝在真实推理栈中的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-20\">二十 · 请求形态与熵预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-21\">二十一 · 长度分布决定批大小上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-22\">二十二 · 并发形态与注意力导出路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-23\">二十三 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-24\">二十四 · 容量规划中的配方表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-25\">二十五 · 配方与相邻方法的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-26\">二十六 · 硬件档位与视觉编码器/LLM 的分离部署</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-27\">二十七 · 并行拓扑：剪枝必须与注意力算子同卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-28\">二十八 · 量化方案：INT8 视觉分支 + INT4 LLM 权重的组合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-29\">二十九 · KV 策略：只保留压缩后视觉 token 的条目</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-30\">三十 · 调度参数：按轮次预留熵重算的前向预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-31\">三十一 · 熵预算的边界条件与部署代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-32\">三十二 · 熵预算的显存账：KV cache 长度随轮次浮动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-33\">三十三 · 带宽与注意力导出的隐藏税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-34\">三十四 · 通信：剪枝点与并行拓扑的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-35\">三十五 · 功耗与算力占比：重算熵的边际成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-36\">三十六 · 尾延迟：多轮漂移下的预算抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-37\">三十七 · 熵预算撞上系统墙：先崩的是注意力导出与轮次重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-38\">三十八 · 熵取不到：融合内核下的可观测性缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-39\">三十九 · 多轮稀释：熵分布被旧轮次污染</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-40\">四十 · 预算过激：细节密集型图像的静默错误</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-41\">四十一 · 批抖动与路由不均：压缩率异质带来的尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-42\">四十二 · OOM 与显存账本：KV cache 长度随轮次漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-43\">四十三 · 监控面与回滚编排</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-44\">四十四 · 同族算法的选择轴：谁在读注意力，谁在改序列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-45\">四十五 · 与一次性输入端剪枝的对照：漂移是否真的存在</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-46\">四十六 · 与逐层压缩、双阶段缩减的对照：改长度还是改预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-47\">四十七 · 与量化感知剪枝、近似误差引导压缩的对照：误差是否联合建模</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-48\">四十八 · 决策表：按负载形态与栈能力选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-era-entropy-prune-sec-49\">四十九 · 选型后的工程落点：预算、内核与回退</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">LLM 前若干层计算文本对视觉 token 的注意力</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对每 token 注意力分布求熵并整流归一化</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按熵排序保留 top-k 视觉 token</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重建压缩后序列并继续解码</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">多轮对话中按轮次重算熵预算</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-era-entropy-prune-sec-1\">一 · 事故现场：一次被“静默剪掉”的视觉证据</h3>\n<p>设想一个已上线的多轮视觉问答服务：用户上传一张设备铭牌照片，第一轮问“这是什么型号”，第二轮问“它的额定电压是多少”，第三轮追问“铭牌上那行小字写的是不是 400V”。前两轮模型答得干净利落，第三轮却给出一个与图像无关的通用电压值，且语气笃定。回放请求后发现：第二轮结束时，视觉 token 已被基于注意力的剪枝压到很小的预算，第三轮解码时序列里根本没有承载那行小字的 token。这不是模型“看不懂”，而是推理栈在用户看不见的地方把证据删掉了。</p>\n<p>这类事故的根因不在解码器，而在剪枝判据本身。基于注意力的视觉 token 剪枝默认一个假设：文本对视觉 token 的注意力权重越高，该 token 越重要。这个假设在单轮、注意力已校准的条件下大致成立；但在跨模态注意力尚未校准的冷启动阶段，注意力打分本身是噪声占优的。模型尚未学会“该看哪里”，权重分布接近均匀或集中在少数位置标记上，此时按权重排序做 top-k，等价于按噪声排序做删除。高信息 token——铭牌上的字符、仪表刻度、表格中的数字——恰恰是那些尚未被注意力“发现”的 token，它们最先被剪掉。</p>\n<p>更隐蔽的是多轮场景。每轮新增的文本会改写注意力分布，历史上下文越长，当前轮的注意力越容易被旧轮次的语义惯性稀释。剪枝预算若在第一轮定死并按固定比例沿用，后续轮次就在一个已经漂移的打分上继续删 token。事故的代价是双重的：答案缺少图像依据（正确性损失），而服务侧毫无告警（可观测性缺失）——剪枝是静默的，SLO 上只看到延迟与吞吐正常，错误率却在细节类问题上抬升。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-2\">二 · 它到底解决什么：注意力未校准与分布漂移下的误删</h3>\n<p>熵引导视觉剪枝针对的正是上面这条失效链，它要解决的具体推理问题是：在跨模态注意力尚未校准、且在多轮对话中持续漂移的条件下，如何决定保留哪些视觉 token，使关键视觉证据不被误删。它的核心主张是把判据从“注意力有多高”换成“注意力有多不确定”。对视觉 token $v_i$，取其收到的注意力分布 $p_i(j)$（第 $j$ 个文本位置对第 $i$ 个视觉 token 的权重），定义熵：</p>\n<div class=\"formula\">$$H_i=-\\sum_{j}p_i(j)\\log p_i(j),\\quad \\text{keep}=\\text{TopK}(H_i)$$</div>\n<p>直觉是：若一个视觉 token 的注意力分散在大量文本位置上、没有哪个位置对它形成压倒性聚焦，说明它的跨模态证据尚未被任何单一语义锚定，因而不可替代，应当保留；反之，若注意力已高度集中，说明该 token 的信息已被某个文本位置“吸收”，压缩它相对安全。熵度量对注意力的绝对尺度不敏感——softmax 温度、头数、层深带来的整体缩放不改变排序，这正是它跨模型迁移性好的原因，也是它相对阈值型硬剪枝更稳的原因。</p>\n<p>配套机制是注意力整流：对读到的注意力分布做归一化与集中化处理，抑制不同头、不同层之间的尺度差异，使跨模态打分在轮次之间可比。工程上这对应一个明确的实现约束——剪枝发生在 LLM 内部前若干层，必须在那些层拿到文本对视觉 token 的注意力矩阵，因此剪枝算子与注意力算子必须同卡，不能把剪枝挪到独立的预处理服务里。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-3\">三 · 它不解决什么：四条明确的边界</h3>\n<p>把边界说清楚比把能力说清楚更重要，因为误用这套算法的代价是静默的正确性损失。</p>\n<ul>\n<li><b>不解决细粒度 OCR 级证据的保留。</b>熵排序偏好“语义分散、不可替代”的 token，而字符级证据往往表现为局部高集中、低熵的形态。当任务需要逐字识别铭牌、票据、表格时，熵判据可能保留一批语义上分散但细节不足的 token，剪掉真正承载字符的那些。这类负载应改用不剪枝、或按空间网格保底保留的策略。</li>\n<li><b>不解决融合注意力内核不导出矩阵的问题。</b>若推理栈使用 FlashAttention 类融合内核且不暴露注意力矩阵，熵无法计算。可行路径是额外导出注意力（走非融合路径或加旁路），代价是吞吐下降与实现复杂度上升；这不是算法能绕过的，是部署前提。</li>\n<li><b>不解决极多视觉 token 的场景。</b>视觉 token 数量极大时，逐 token 求熵与排序的开销、以及每轮重算的前向开销会挤占预算，收益被成本吃掉。它适合视觉 token 数量中等的负载。</li>\n<li><b>不与量化误差联合优化。</b>它只处理注意力未校准与漂移，不建模 INT8 视觉分支、INT4 LLM 权重带来的数值扰动；量化感知剪枝是另一条路线，两者可以叠加但不能互相替代。</li>\n</ul>\n<p>与相邻算法的分工也要划清：与一次性输入端剪枝不同，它的判据来自 LLM 内部注意力而非外部打分器；与逐层压缩不同，它不改变层间序列长度，而是每轮重设预算；与视觉缓存复用不同，它处理的是“删哪些”，不是“复用哪些”。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-4\">四 · 代价账本：每轮重算熵买到了什么</h3>\n<p>这套算法的成本结构非常清晰：收益来自更准的保留决策，成本来自在 LLM 内部多读一次注意力、多算一次熵、多排一次序，并且这个成本按轮次重复支付。设保留预算为 $k$、视觉 token 数为 $n_v$、历史长度为 $L_h$，则每轮的额外开销由三部分组成：注意力导出（与 $n_v \\times L_h$ 的注意力规模同阶）、逐 token 熵计算（$O(n_v \\cdot L_h)$ 的归约）、以及 top-k 排序（$O(n_v \\log n_v)$）。相对一次完整前向，这部分占比随轮次与上下文长度上升而上升，因此容量规划必须按“轮次 × 上下文”预留额外前向时间，而不是按单轮估算。</p>\n<p>对 SLO 的影响落在两处：首 token 延迟（TTFT）与每轮增量延迟（TBT/轮间延迟）。首轮剪枝发生在预填之后、解码之前，直接抬高 TTFT；后续轮次的重算熵发生在每轮开始，抬高轮间延迟。工程上的缓解手段是预算分层：首轮用较宽的 $k$ 保证证据不被早期误删，后续轮次按当前上下文重算熵预算并逐步收紧；长多轮会话宜用小批，因为批大小同时受视觉 token 数与历史长度约束，大批会把每轮的重算开销放大成尾延迟。</p>\n<p>显存侧的账要单独算：KV cache 只保留压缩后视觉 token 对应的条目，长度随轮次变化，这带来一个实现细节——KV cache 的分配不能按最大轮次静态预留，否则压缩收益被预留浪费掉；需要按轮次动态伸缩，或按会话维度做分页管理。这与连续批处理的调度器耦合：批内不同请求处于不同轮次、不同压缩长度，调度器必须能处理长度不齐的视觉段。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-5\">五 · 一个具体例子：三轮对话里的预算重设</h3>\n<p>回到铭牌场景，用这套算法走一遍数据流。视觉 token 与文本 token 拼接后进入 LLM 前若干层；在这些层读取文本对视觉 token 的注意力，得到每个 $v_i$ 的分布 $p_i(j)$；对每个 token 求 $H_i$ 并整流归一化，得到打分 $s_i=H_i/\\sum_k H_k$；按 $s_i$ 降序保留 top-k；重建压缩后的序列继续解码。</p>\n<p>第一轮问“这是什么型号”：注意力尚未校准，分布弥散，熵普遍偏高，排序区分度低。此时若强行按固定小预算剪枝，等于随机删除。正确做法是首轮给宽预算，让模型在较完整的视觉序列上完成第一次校准。第二轮问“额定电压”：注意力开始向铭牌中部的参数区集中，该区域 token 的熵下降（已被锚定），而铭牌边缘的小字行仍保持较高熵——它们尚未被任何文本位置锁定，因而被保留。第三轮追问小字：由于第二轮没有把这些高熵 token 删掉，第三轮解码时它们仍在序列中，模型得以给出有图像依据的回答。</p>\n<p>这个例子揭示了算法的关键工程判断：预算不是常数，而是轮次的函数。每轮按当前上下文重算熵，等于把“哪些证据还没被用上”作为保留依据，而不是把“哪些证据上一轮被看得多”作为删除依据。代价是每轮一次额外前向，收益是跨轮次的证据连续性。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-6\">六 · 稳定性技巧与失效模式：什么时候它会反过来害你</h3>\n<p>整流归一化是这套算法的稳定器：它抑制不同头、不同层、不同轮次之间的注意力尺度差异，使熵排序在轮次间可比，避免阈值型硬剪枝在分布轻微抖动时产生保留集合的跳变。熵排序本身也比阈值判据稳——排序只依赖相对次序，不依赖绝对阈值，因而对模型版本迁移更宽容。</p>\n<p>但它有三条明确的失效模式，部署前必须逐条排查。其一，融合内核不导出注意力矩阵：熵算不出来，只能加旁路导出，吞吐下降且实现复杂，这是部署前提而非调参问题。其二，多轮历史过长稀释当前轮注意力：旧轮次的文本持续占据注意力份额，熵分布被污染，本轮关键证据可能被误判为低熵而剪除；缓解手段是按轮次衰减历史权重或限制参与熵计算的历史窗口，但这会改变判据语义，需与业务侧确认。其三，top-k 按固定比例设置时遇到细节密集型图像：预算过激会剪掉过多 token，答案出现物体属性错误或文字识别错误；这类负载应改用绝对预算下限加空间保底，而非纯比例。</p>\n<p>工程判断落在最后这一点上：熵引导剪枝的适用边界是“视觉 token 数量中等、多轮对话为主、证据以语义对象而非字符细节为主”的负载。越过这条边界，它不是变慢，而是静默地变错——而静默的错误，比慢更贵。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-7\">七 · 剪枝边界：熵信号在哪些推理栈里会失效</h3>\n<p>这套方案要解决的不是\"视觉 token 太多\"这个笼统问题，而是一个更窄的失效面：<strong>基于注意力的视觉剪枝在跨模态注意力尚未校准时会误删高信息 token</strong>。典型事故形态是这样的——线上多轮图文客服，第一轮用户上传一张设备铭牌照片并问型号，模型答对；第二轮追问\"铭牌上第三行序列号是多少\"，此时语言侧注意力已被前一轮的对话历史牵引，大量权重落在历史文本 token 上，视觉 token 收到的注意力分布被摊薄，按注意力阈值硬剪的路径把铭牌区域的细粒度 token 判为低分直接丢弃，模型只能凭第一轮的语义摘要作答，序列号输出错误。事故根因不在视觉编码器，而在打分器：注意力权重本身随轮次漂移，阈值型剪枝对这种漂移没有免疫力。熵引导的做法是把打分对象从\"注意力大小\"换成\"注意力分布的弥散程度\"：对视觉 token $v_i$ 取其收到的注意力分布 $p_i(j)$（第 $j$ 个文本位置对第 $i$ 个视觉 token 的权重），令</p>\n<div class=\"formula\">$$H_i=-\\sum_{j}p_i(j)\\log p_i(j),\\qquad s_i=\\frac{H_i}{\\sum_{k}H_k},\\qquad \\text{keep}=\\text{TopK}(s_i)$$</div>\n<p>熵高意味着该 token 的证据被多个文本位置分散引用、不可替代性强，因而优先保留；整流归一化 $s_i$ 抹平了不同层、不同头之间的注意力尺度差异，这正是它对跨模型迁移友好的原因。但它不解决的问题同样清晰：它不联合量化误差做决策，因此 INT4 权重下由量化引入的数值退化不在它的覆盖范围内；它也不改变层间序列长度，逐层压缩那类方案要处理的层内冗余与它无关；它与一次性输入端剪枝的分工在于决策位置——剪枝发生在 LLM 内部而非编码器出口。</p>\n<p>失效条件集中在三处，且都带明确的系统代价。<strong>其一，融合注意力内核不导出注意力矩阵</strong>：若推理栈走 FlashAttention 融合路径，中间注意力不被物化，熵无从计算，必须额外开一条导出通路，这条通路打断算子融合、增加显存往返，吞吐下降且实现复杂度上升——这是部署前必须先确认的栈能力，而不是运行时再补救。<strong>其二，多轮历史稀释</strong>：上下文越长，旧轮次文本对视觉 token 的注意力占比越高，$p_i(j)$ 被历史污染，本轮关键证据可能被误判为低熵而剪除；缓解手段是每轮按当前上下文重算熵预算而非沿用固定比例，代价是每轮多一次前向读取，首 token 延迟与每轮增量延迟的 SLO 预算必须按轮次预留额外前向时间，长会话宜配小批。<strong>其三，top-k 过激</strong>：固定保留比例遇到细节密集型图像（OCR 级文字、物体属性）会剪掉过多 token，熵排序偏向保留语义分散的 token，而细节证据往往集中在少数低熵但高价值的 token 上。</p>\n<table class=\"mini\"><thead><tr><th>边界维度</th><th>成立条件</th><th>失效表现与代价</th></tr></thead><tbody><tr><td>注意力可取</td><td>非融合内核或可导出路径</td><td>融合内核下熵不可算，需额外导出，吞吐下降</td></tr><tr><td>轮次深度</td><td>历史长度可控、每轮重算预算</td><td>旧轮次稀释熵分布，误删本轮证据；每轮额外前向开销</td></tr><tr><td>视觉 token 规模</td><td>中等 token 数、多轮对话为主</td><td>极多 token 或细粒度 OCR 场景下细节证据丢失</td></tr></tbody></table>\n<p>由此得到适用边界的工程判断：该方案适合视觉 token 数量中等、以多轮对话为主、且推理栈能低代价暴露注意力的场景；规模上限不由 token 数单独决定，而由\"每轮重算熵的前向开销占总解码时间比例\"约束——轮次越多、上下文越长，这笔开销占比越高，直到剪枝省下的 prefill 与 KV 显存收益被重算成本抵消。部署形态上，剪枝发生在 LLM 内部，必须与注意力算子同卡，视觉编码器则可分离部署；KV cache 只保留压缩后视觉 token 对应条目，长度随轮次变化，容量规划要按轮次峰值而非首轮静态值预留。</p>\n<h3 id=\"alg-era-entropy-prune-sec-8\">八 · 从拼接序列到首次取熵：视觉 token 的入口与注意力读取点</h3>\n<p>熵引导视觉剪枝的第一个动作发生在视觉编码器输出之后、LLM 解码之前的那段拼接序列上。视觉 token 与文本 token 被拼成一条序列送入 LLM 的前若干层，剪枝决策只在这些层里做，不在编码器侧做。输入是完整的视觉 token 集合与当前轮文本上下文，输出是一份对每个视觉 token 的注意力分布采样。代价落在两处：一是拼接后序列变长，prefill 的注意力计算量随视觉 token 数线性上升；二是必须在前若干层保留一条能读出注意力矩阵的路径。Blackwell 上若推理栈走的是融合注意力内核（FlashAttention 类），注意力矩阵默认不落回显存，取熵就需要额外的导出分支，这条分支本身带来一次额外的写回与同步，是这一步骤最容易被低估的吞吐代价。</p>\n<p>取熵的位置选择有工程含义。层数太浅，跨模态注意力尚未成形，文本对视觉 token 的分配接近均匀，熵值区分度低；层数太深，则剪枝收益被前段已经付出的完整注意力计算吃掉。因此这一步的输入还包括一个层区间参数，输出是区间内若干层注意力分布的聚合视图。聚合方式可以是逐层平均，也可以是取最后一层的分布，前者抗抖动、后者更贴近最终语义。无论哪种，读取点的存在都要求调度器在 prefill 阶段为这批请求预留一条非融合路径，批内混合了走融合内核的请求与走导出路径的请求时，内核切换会打断连续批处理的流水。</p>\n<p>具体例子：一个请求携带一张文档图像，视觉 token 数为中等规模，文本侧是第二轮追问。前若干层里，文本位置对图像区域 token 的注意力已经出现明显分化——标题区与表格线附近收到较高权重，空白边距几乎为零。这一步不删任何 token，只是把这份分布取出来交给下一步求熵。若此时栈内注意力被融合内核吞掉，工程上要么临时切到导出内核、要么在融合内核里加一个可选输出口，两者都要在批调度层面显式声明，否则该请求无法进入熵剪枝路径。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-9\">九 · 熵与整流：把注意力分布折算成可排序的不确定性分数</h3>\n<p>拿到分布后，对每个视觉 token $v_i$ 取其收到的注意力分布 $p_i(j)$，其中 $p_i(j)$ 表示第 $j$ 个文本位置对第 $i$ 个视觉 token 的注意力权重。熵定义为</p>\n<div class=\"formula\">$$H_i=-\\sum_{j}p_i(j)\\log p_i(j)$$</div>\n<p>直觉是：若所有文本位置对该视觉 token 的注意力都差不多，说明这个 token 被多处证据引用、不可替代，熵高；若注意力集中在单一文本位置，说明它只服务一个局部查询，熵低。这一步的输入是上一步取到的分布，输出是每个视觉 token 的标量 $H_i$。代价是逐 token 的归约运算，规模与视觉 token 数乘以文本长度成正比，在 prefill 阶段属于轻量算子，但它插在注意力与后续层之间，会打断算子融合链，引入一次 kernel launch 与一次全局同步。</p>\n<p>整流是这一步的关键工程动作。原始注意力在不同头、不同层之间尺度差异很大，直接比较熵会被尺度主导。整流归一化把打分压成</p>\n<div class=\"formula\">$$s_i=\\frac{H_i}{\\sum_{k}H_k}$$</div>\n<p>再按 $s_i$ 降序保留 top-k。归一化的作用不是改变排序，而是让预算分配在不同轮次、不同请求之间可比——多轮对话里每轮的注意力总量会漂移，若不归一，上一轮残留的高尺度会污染本轮的预算判断。代价上，归一化需要一次跨 token 的求和归约，属于块内 reduction，在 Blackwell 的 TMEM 与共享内存之间来回搬运一次即可，但若视觉 token 数很大，这次归约的延迟会体现在首 token 延迟上。</p>\n<p>具体例子：一张商品图里，主体轮廓 token 被“这是什么”“什么颜色”“有没有划痕”三个文本位置共同关注，分布接近均匀，$H_i$ 高；而背景纹理 token 只被一个位置轻微关注，$H_i$ 低。整流后前者 $s_i$ 明显靠前，进入保留集。这里不涉及任何阈值判断，排序本身承担了决策，避免了阈值型硬剪枝在轮次间抖动的问题。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-10\">十 · top-k 保留与序列重建：压缩后的 KV 布局</h3>\n<p>排序完成后按 $s_i$ 取前 k 个视觉 token，其余丢弃，然后重建压缩后的序列继续解码。输入是排序后的打分与原始 token 序列，输出是一条变短的序列以及与之对应的位置编码重排。代价分三块：重建本身是一次 gather，按保留索引从原序列搬运 token 的 hidden state 与 KV，搬运量等于保留 token 数乘以隐藏维度；位置编码需要重新连续化，否则后续层的注意力位置偏置会错位；KV cache 只保留压缩后视觉 token 对应的条目，长度随轮次变化，这使批内各请求的 KV 长度不再一致，连续批处理的块表需要按请求单独维护。</p>\n<p>top-k 的 k 不是固定比例就万事大吉。固定比例在细节密集型图像上会剪掉过多 token，导致物体属性或文字识别出错；比例过松则压缩收益消失。工程上 k 应随本轮熵分布的集中程度调整：熵分布平坦说明证据分散，需要更大 k；熵分布陡峭说明少数 token 承载主要证据，可以更激进。这一步的输出因此还包含一个本轮实际保留数，供调度器更新该请求的 KV 占用估计。</p>\n<p>具体例子：同一张文档图在第三轮被问及表格中某一格的数值。若 k 按固定比例取，表格线附近的细粒度 token 可能被整体剪掉，答案失去图像依据；若 k 随熵分布放宽，保留集覆盖到该格所在区域，解码继续时该区域的 KV 条目仍在缓存中。代价是这一轮 KV 占用上升，批内可容纳的并发请求数下降，容量规划需要把“轮次相关的 KV 波动”计入显存预算，而不是按首轮压缩后的固定长度静态分配。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-11\">十一 · 多轮重算：每轮重设熵预算与前向开销</h3>\n<p>多轮对话中，历史文本会稀释当前轮对视觉 token 的注意力，熵分布被旧轮次污染，本轮关键证据可能被误判为低熵而剪除。机制上的应对是每轮按当前上下文重算熵预算，而不是沿用首轮保留集。输入是累积的历史上下文加上本轮查询，输出是本轮新的保留索引与新的 KV 布局。代价是每轮都要重新走一遍前若干层的注意力读取与熵计算，这部分前向开销随轮次与上下文长度增长，在长会话里占推理总算力的比例上升，规模上限正受此约束。</p>\n<p>这一步与连续批处理的交互最紧密。每轮重算意味着同一请求在不同轮次之间的计算图不同，块表要在轮次边界重建，已缓存的 KV 中视觉部分需要按新索引重排或部分失效。若调度器把多轮请求当作独立请求拼接进批，重算开销会被重复计入；若按会话粘性调度，则要保证同一会话的轮次落在能读到注意力的同一张卡上——剪枝发生在 LLM 内部，与注意力算子同卡是硬约束，跨卡重算会引入一次不必要的激活搬运。</p>\n<p>具体例子：一个五轮会话，首轮问整体场景，末轮问画面角落的小字。首轮保留集偏向主体，末轮重算后角落区域 token 的熵因当前查询的集中关注而升高，重新进入保留集。代价是末轮的首 token 延迟包含一次完整的前若干层重算，SLO 预算需按轮次预留额外前向时间，而不是按首轮延迟线性外推。长多轮会话宜用小批，正是因为每轮重算的固定开销摊薄在更少的请求上会更贵。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-12\">十二 · 失败模式与部署约束：取不到熵、稀释与过激</h3>\n<p>最硬的失败模式是取不到熵：推理栈使用融合注意力内核且不暴露注意力矩阵时，熵无法计算，需额外导出路径，吞吐下降且实现复杂。这不是算法问题而是栈能力问题，部署前必须确认所用内核是否提供可选注意力输出口，否则整条路径不可用。第二个失败模式是多轮历史过长使熵估计被旧轮次稀释，表现为本轮关键证据被判低熵剪除，缓解手段是整流归一化加上按轮次重设预算，但两者都不能完全消除长上下文的污染，只能把误删概率压到可接受区间。第三个是 top-k 过激，在细节问答上丢证据，表现为物体属性或文字识别错误，缓解手段是让 k 随熵分布自适应。</p>\n<p>部署配方上，硬件档位为单卡或双卡 Blackwell，视觉编码器与 LLM 可分离部署，但剪枝发生在 LLM 内部故需与注意力算子同卡；并行拓扑以张量并行为主；量化可与 INT8 视觉分支、INT4 LLM 权重组合，熵计算本身在注意力分数上做，与权重精度解耦，因此量化不改变排序逻辑，只改变读取注意力的数值噪声水平。KV cache 仅保留压缩后视觉 token 对应的条目，长度随轮次变化，容量规划要按会话轮次分布做加权估计而非按峰值静态预留。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>注意力读取</td><td>拼接序列、层区间</td><td>文本对视觉 token 的分布</td><td>融合内核需导出路径，prefill 吞吐下降</td></tr><tr><td>求熵与整流</td><td>分布 $p_i(j)$</td><td>打分 $s_i$</td><td>逐 token 归约与跨 token 求和，首 token 延迟上升</td></tr><tr><td>top-k 与重建</td><td>打分、原序列</td><td>压缩序列、新 KV 布局</td><td>gather 搬运、位置重排、块表按请求维护</td></tr><tr><td>多轮重算</td><td>累积上下文、本轮查询</td><td>本轮保留索引</td><td>每轮额外前向，长会话算力占比上升</td></tr></tbody></table>\n<p>工程判断落在取熵路径的可得性上：这条算法的收益完全依赖能否在 LLM 内部低成本读到注意力。若栈内只能走融合内核且无导出口，替代方案是在前若干层单独跑一条非融合的注意力旁路，只算分布不算完整输出，代价是一次额外的前向片段；若连旁路都不允许，则熵剪枝在该栈上不可部署，应退回输入端剪枝。反过来，若栈已支持注意力导出，则整流归一化与按轮次重设预算这两步是必须保留的，它们分别对应尺度稳定与漂移抑制，去掉任一步，多轮场景下的误删率都会回到未校准注意力的水平。</p>\n<h3 id=\"alg-era-entropy-prune-sec-13\">十三 · 熵的定义与逐项拆解</h3>\n<p>对第 <em>i</em> 个视觉 token <em>v<sub>i</sub></em>，记 <em>p<sub>i</sub></em>(<em>j</em>) 为第 <em>j</em> 个文本位置回看该视觉 token 的注意力权重，并已在该文本维度上归一化（∑<sub>j</sub> <em>p<sub>i</sub></em>(<em>j</em>) = 1）。核心度量是这条分布的香农熵：</p>\n<div class=\"formula\">$$H_i=-\\sum_{j}p_i(j)\\log p_i(j),\\quad \\text{keep}=\\text{TopK}(H_i)$$</div>\n<p>逐项看：<em>p<sub>i</sub></em>(<em>j</em>) 不是视觉 token 对文本的注意力，方向必须反过来——是文本在生成/编码时“看”到了哪个视觉位置。这个方向决定了熵的语义：若某个视觉 token 只被一个文本位置强烈关注、其余位置几乎为零，则 <em>p<sub>i</sub></em> 接近 one-hot，<em>H<sub>i</sub></em> 趋近 0，说明该证据可被单一文本锚点替代；若注意力被摊薄到大量文本位置上，<em>H<sub>i</sub></em> 升高，说明这块视觉内容被多处引用、不可替代，应当保留。因此“熵高者保留”不是启发式，而是把“跨模态证据的不可替代性”翻译成了分布分散度。</p>\n<p>推导的关键一步在于把 softmax 的尺度因子剥离出去。注意力 logits 常带温度与长度相关的缩放，直接比较不同层、不同头、不同轮次的原始注意力会引入尺度漂移；而对已归一化的 <em>p<sub>i</sub></em> 取熵，等价于只保留分布的“形状”信息，丢弃幅度信息。这就是熵度量对注意力尺度不敏感、跨模型迁移性好的来源——它比较的是排序结构而非绝对分值。工程代价上，这一步要求在 LLM 内部真实拿到注意力矩阵，而 FlashAttention 类融合内核默认不物化该矩阵，必须走额外导出路径，直接体现为带宽与显存写出的开销，并压低可达吞吐。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-14\">十四 · 整流归一化与打分公式</h3>\n<p>原始熵在不同头、不同层之间量纲一致但分布范围不同，若直接跨头聚合，少数头的高熵会淹没其余头。因此在保留前先做整流：</p>\n<div class=\"formula\">$$s_i=\\frac{H_i}{\\sum_{k}H_k}$$</div>\n<p>分母是对当前候选视觉 token 集合的熵求和，于是 <em>s<sub>i</sub></em> 构成一个单纯形上的权重，TopK 变成在归一化预算内做分配，而非依赖绝对阈值。整流的作用有两层：其一把“保留多少”从硬阈值改为相对比例，避免阈值型剪枝在注意力轻微抖动时反复翻转保留集合；其二把多头、多层读数压到同一标尺，使跨层比较成为可能。伪代码落到可实现层面，关键是“读注意力—算熵—整流—重排—重建”这条链要在一次前向内闭合：</p>\n<ul>\n<li>在前若干层注册注意力读取钩子，只取文本 query 对视觉 key 的那一列切片，避免整矩阵导出；</li>\n<li>对每个视觉 token 沿文本维归一化得到 <em>p<sub>i</sub></em>，累加 −<em>p</em> log <em>p</em> 得 <em>H<sub>i</sub></em>，多头取加权和后再整流；</li>\n<li>按 <em>s<sub>i</sub></em> 降序取 top-<em>k</em>，记录保留索引；</li>\n<li>用索引对视觉 token 张量做 gather，重建拼接序列，继续后续层解码；</li>\n<li>多轮场景下每轮以当前上下文重算 <em>H<sub>i</sub></em> 与预算 <em>k</em>，不复用上一轮排序。</li>\n</ul>\n<p>系统代价集中在两处：读取切片的显存写出量与 gather 造成的序列重排。前者与层数×头数×视觉 token 数成正比，后者打断连续布局，迫使后续算子重新做 layout 转换；在长上下文多轮会话中，这两项叠加会把每轮增量延迟推高，因此预算必须按轮次预留额外前向时间，长会话宜配小批。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-15\">十五 · 为什么熵优于注意力幅值</h3>\n<p>注意力幅值型剪枝隐含假设“被关注多的 token 更重要”，但跨模态注意力未校准前，幅值受文本长度、位置编码与头 specialization 影响，同一视觉证据在不同轮次可能得到截然不同的分值。熵只问“这条证据是否被多处引用”，对幅值单调变换不变，因而在多轮漂移下更稳。举例：一张含表格的图片，表头被多个提问反复引用，其 <em>p<sub>i</sub></em> 分散在多处文本上，<em>H<sub>i</sub></em> 高而被保留；而某个仅被首轮问候语扫过的装饰性区域，<em>p<sub>i</sub></em> 集中于单一位置，熵低而被剪。若改用幅值排序，首轮问候语可能给出极高幅值，反而把装饰区排在表头之前。</p>\n<p>代价是熵对“分散但无信息”的 token 也友好：背景纹理若被大量文本位置以低权重均匀扫过，熵同样偏高，会挤占预算。这构成本方法的结构性弱点，在细节密集型图像（OCR 级文字、物体属性）上尤为明显——top-<em>k</em> 过激时保留的多是语义分散的 token，细节证据被剪掉，答案出现识别错误。工程上的缓解不是调阈值，而是让 <em>k</em> 随图像复杂度与轮次动态伸缩，并把整流分母限制在当前轮相关文本子集上，减少旧轮次对熵分布的稀释。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-16\">十六 · 多轮预算重算的递推视角</h3>\n<p>设第 <em>r</em> 轮上下文长度为 <em>L<sub>r</sub></em>，视觉 token 数为 <em>N<sub>v</sub></em>，保留预算 <em>k<sub>r</sub></em>。每轮重算熵的额外前向开销可写成与 <em>N<sub>v</sub></em>×<em>L<sub>r</sub></em> 成正比的读出项加上一次重排项：</p>\n<div class=\"formula\">$$\\Delta T_r \\;\\propto\\; N_v \\cdot L_r \\cdot d_{\\text{head}} \\cdot n_{\\text{layer}}^{\\text{read}}$$</div>\n<p>其中 <em>n</em><sup>read</sup><sub>layer</sub> 是参与读取的前若干层数，<em>d</em><sub>head</sub> 为头维。该式说明额外算力占比随轮次单调上升：<em>L<sub>r</sub></em> 增长而 <em>N<sub>v</sub></em> 不变时，读出项线性膨胀，最终可能吞掉剪枝带来的解码节省。因此预算策略应是“轮次越深、<em>k<sub>r</sub></em> 越保守地下调”，而不是固定比例。伪代码上表现为一个按轮次索引的预算表，配合一个滑动窗口把参与熵计算的文本位置限制在最近若干轮，既控制 <em>L<sub>r</sub></em> 的有效长度，也抑制旧轮次污染。</p>\n<p>KV cache 侧随之变化：仅保留压缩后视觉 token 对应的条目，缓存长度随轮次与 <em>k<sub>r</sub></em> 波动，导致批内序列长度不齐，连续批处理需要更细的 padding 或分桶策略；这是把“每轮重设预算”落到调度器上的真实代价，而非算法本身的代价。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-17\">十七 · 失败模式对应的实现约束</h3>\n<p>第一类失败是内核不导出注意力矩阵。若推理栈使用融合注意力且不暴露中间矩阵，熵无从计算，只能退回幅值型打分或关闭剪枝；补救路径是单独开一条读出通路，代价是吞吐下降与实现复杂度上升，且该通路必须与注意力算子同卡，因为剪枝发生在 LLM 内部，跨卡搬运注意力切片会引入 NVLink 往返。第二类失败是历史稀释：多轮文本越长，当前轮对视觉 token 的注意力被旧轮次摊薄，熵分布被污染，本轮关键证据可能被判为低熵而剪除；实现上必须以当前轮 query 为条件重算，而非对全历史求平均。第三类失败是固定 top-<em>k</em> 比例遇到细节密集图像，剪掉过多 token。</p>\n<p>稳定性技巧因此落在两处：整流归一化抑制尺度差异带来的排序抖动；熵排序替代硬阈值，使保留集合在注意力小幅波动时保持连续。工程判断上，是否启用本方法取决于能否接受“每轮一次额外读出前向”——在单卡或双卡 Blackwell 上，视觉编码器与 LLM 可分离部署、以张量并行为主，读出通路与注意力同卡即可闭合；若 SLO 以首 token 延迟为主且轮次很深，额外前向占比会逼近预算上限，此时应把读出层数压到最少、把熵计算限制在最近窗口，用精度换延迟，而不是放弃剪枝退回全量视觉 token。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-18\">十八 · 整流项与熵预算的失效边界：从公式到可落地的伪代码</h3>\n\n<p>核心公式的工程含义不在熵本身，而在整流项 $s_i=H_i/\\sum_k H_k$ 与 top-k 的耦合方式。对视觉 token $v_i$，$p_i(j)$ 是第 $j$ 个文本位置回看该视觉 token 的注意力权重，$H_i=-\\sum_j p_i(j)\\log p_i(j)$ 度量的是\"证据分散度\"：熵高说明该 token 被多个文本位置以相近权重引用，语义上不可替代；熵低则说明它只被单一位置弱引用，接近冗余。整流归一化把逐 token 的熵压到同一量纲，使 top-k 的阈值随轮次与上下文长度自适应漂移，而不是固定比例硬切。这一步是方案对注意力尺度不敏感、可跨模型迁移的直接来源——它比较的是分布形状而非绝对注意力值，因此换模型、换层深不必重标定阈值。</p>\n\n<p>推导的关键一步在于把\"保留决策\"从注意力幅值转移到分布熵上：注意力幅值受 softmax 温度、层归一化与 RoPE 相位共同影响，跨模态未校准时会系统性偏向某些文本位置，直接按幅值排序必然误删；而熵对幅值的单调缩放不变，只对分布的集中程度敏感。伪代码落到可实现层面，需明确三个接口：读取层区间、整流归一化、预算重设。示意如下——在 LLM 前若干层挂一个注意力导出钩子，收集文本查询对视觉键的权重矩阵 $A\\in\\mathbb{R}^{L_t\\times L_v}$，按列归一化得 $p_i(j)$，逐列求熵得 $H_i$，整流后降序取 top-k 索引集 $\\mathcal{K}$，再用索引重建压缩序列并继续解码；多轮场景下每轮以当前上下文重算 $\\mathcal{K}$，而非沿用上一轮预算。</p>\n\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>融合内核不导出注意力</td><td>FlashAttention 前向不落地 $L_t\\times L_v$ 矩阵</td><td>需旁路导出，吞吐下降、实现复杂度上升</td></tr><tr><td>历史稀释当前轮</td><td>旧轮次文本占据多数查询位置，$H_i$ 被污染</td><td>本轮关键证据被判低熵剪除，答案缺图像依据</td></tr><tr><td>固定 top-k 比例</td><td>细节密集型图像 token 分布平坦</td><td>剪除过多，物体属性与文字识别出错</td></tr></tbody></table>\n\n<p>系统代价必须按轮次计入预算：每轮重算熵意味着在解码前多一次前向读取，其开销与视觉 token 数、历史长度、读取层数三者乘积成正比，轮次越多、上下文越长，这部分额外算力在端到端延迟中的占比越高。部署上剪枝发生在 LLM 内部，必须与注意力算子同卡，张量并行下熵的归约需跨卡同步，双卡 Blackwell 档位宜把视觉编码器与 LLM 分离部署以腾出显存给 KV cache；KV cache 只保留压缩后视觉 token 对应的条目，长度随轮次变化，批大小受视觉 token 数与历史长度共同约束，长多轮会话应主动降批以守住首 token 延迟与每轮增量延迟的 SLO。适用边界因此清晰：视觉 token 数量中等、以多轮对话为主时收益稳定；视觉 token 极多或需 OCR 级细粒度证据时，熵排序倾向保留语义分散但细节不足的 token，此时应改用固定比例与熵排序的混合预算，或对细节区域单独豁免剪枝。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-19\">十九 · 边界、失效条件与系统代价：熵剪枝在真实推理栈中的落点</h3>\n<p>熵剪枝的适用边界由“注意力可读”与“熵可估”两条硬约束划出。若推理栈使用融合注意力内核且不暴露注意力矩阵，$H_i=-\\sum_{j}p_i(j)\\log p_i(j)$ 根本无从计算，必须额外走一条导出路径把注意力权重落回显存，这既增加实现复杂度，也让吞吐下降——融合内核之所以快，正是因为它不物化中间矩阵。第二个失效条件是历史稀释：多轮对话中旧轮次文本持续向视觉 token 分走注意力，$p_i(j)$ 被污染，本轮真正关键的视觉证据可能呈现低熵而被误判剪除。第三个失效条件是预算刚性：top-k 按固定比例设置时，细节密集型图像（密集文字、小目标属性）会被剪掉过多 token，答案出现物体属性或文字识别错误。规模上限则受每轮重算熵的前向开销约束，轮次越多、上下文越长，额外算力占比越高。</p>\n<div class=\"formula\">$$\\text{overhead}_{r}\\approx\\frac{T_{\\text{probe}}(L_r,\\,N_v)}{T_{\\text{decode}}(L_r,\\,N_v-k)},\\quad \\text{keep}=\\text{TopK}\\!\\left(\\frac{H_i}{\\sum_k H_k}\\right)$$</div>\n<p>把代价写清楚：每轮需在 LLM 前若干层做一次探针前向，读取文本对视觉 token 的注意力并整流归一化，再排序保留 top-k、重建压缩序列继续解码。探针开销与历史长度 $L_r$、视觉 token 数 $N_v$ 同阶增长，而剪枝收益只体现在后续解码步的序列变短上；短回复、多轮、长历史的会话里，探针占比会逼近甚至超过剪枝省下的时间。工程判断因此落在预算按轮次动态预留：首 token 延迟里含探针，每轮增量延迟里含重算，SLO 需按轮次而非按请求整体预留额外前向时间。批大小同时受视觉 token 数与历史长度约束，长多轮会话宜用小批，否则探针与解码争抢同一份算力。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统后果</th></tr></thead><tbody><tr><td>融合内核不导出注意力</td><td>无 $p_i(j)$ 可读</td><td>需旁路导出，吞吐下降</td></tr><tr><td>历史轮次稀释</td><td>熵分布被旧轮污染</td><td>本轮证据误剪，答案缺图依据</td></tr><tr><td>top-k 固定比例</td><td>细节密集图像被过剪</td><td>属性/OCR 类错误上升</td></tr></tbody></table>\n<p>部署侧还有一条容易被忽略的耦合：剪枝发生在 LLM 内部，必须与注意力算子同卡，张量并行切分后熵的归约要跨卡对齐，否则各 rank 上的 top-k 不一致会撕裂压缩序列；KV cache 仅保留压缩后视觉 token 对应的条目，长度随轮次变化，缓存分配器需支持按轮收缩而非一次性预留。量化可与 INT8 视觉分支、INT4 LLM 权重组合，但熵排序本身对注意力尺度不敏感，整流归一化 $s_i=H_i/\\sum_k H_k$ 抑制了尺度差异，这也是它跨模型迁移性好的原因——代价是不能与量化误差联合优化，剪枝决策与量化噪声各自独立生效。真正决定这套方案能否上线的，不是熵公式本身，而是探针前向能否被摊薄到可接受的首 token 延迟预算内。</p>\n<h3 id=\"alg-era-entropy-prune-sec-20\">二十 · 请求形态与熵预算的耦合</h3>\n<p>熵引导视觉剪枝的负载画像非常窄：它要的是「一张图 + 多轮文本」的请求，且每轮都携带历史上下文。原因在于机制的输入不是图像本身，而是语言侧对视觉 token 的注意力分布。单轮 VQA 请求里，注意力在首轮就已集中，熵排序的收益有限；而多轮对话中，每轮用户追问都会重新分配注意力，上一轮被判定为低熵的 token 可能在下一轮变成关键证据。因此这套方法的负载配方第一条就是：请求必须存在「轮次」这个维度，否则重算熵的机制根本无从发挥。</p>\n<p>熵预算的分配直接绑定请求形态。设第 $r$ 轮保留的视觉 token 数为 $k_r$，则整条请求的视觉侧计算量近似为 $\\sum_{r=1}^{R} k_r \\cdot L_{\\text{LLM}}$，其中 $L_{\\text{LLM}}$ 是参与熵读取的前若干层深度。若固定 $k_r=k$，总视觉 token 处理量随轮次线性增长；若按轮次递减预算，则后轮上下文越长、视觉证据越容易被稀释。工程上的判断是：轮次少（2–3 轮）且每轮追问指向同一区域时，固定预算可用；轮次多且追问跳转不同区域时，必须按轮重设预算，否则熵排序会系统性偏向旧轮次已经激活过的 token。</p>\n<p>一个具体例子：用户上传一张仪表盘截图，第一轮问「总体状态」，第二轮问「右下角告警灯的颜色」，第三轮问「告警灯旁边的数值」。首轮注意力分散在整图，熵值普遍偏高，保留的 top-k 覆盖全局；第二轮注意力收缩到右下角，若仍沿用首轮预算，右下角 token 的熵在新分布下升高但排序位置未必进入 top-k，因为旧轮次的分散注意力仍在历史上下文里贡献权重。这就是负载形态与机制不匹配的典型代价：答案缺少图像依据，而延迟并未下降，因为每轮重算熵的前向开销照付。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-21\">二十一 · 长度分布决定批大小上限</h3>\n<p>批大小在这套方法里不是独立参数，而是被视觉 token 数与历史长度共同夹住的因变量。显存占用可写成 $M \\approx M_{\\text{vis}} + M_{\\text{hist}} + M_{\\text{KV}}$，其中 $M_{\\text{vis}}$ 随保留的 top-k 视觉 token 数变化，$M_{\\text{hist}}$ 随轮次累积的文本历史线性增长，$M_{\\text{KV}}$ 只保留压缩后视觉 token 对应的条目。长多轮会话中 $M_{\\text{hist}}$ 是主导项，此时唯一可行的做法是小批：批内每条请求的历史长度差异越大，padding 浪费越严重，而熵读取发生在 LLM 前若干层，padding token 同样要过注意力，等于用有效算力去算无意义的熵。</p>\n<p>长度分布的另一端是视觉 token 数的分布。中等视觉 token 量（单图几十到几百个 patch）时，top-k 剪枝后序列长度显著缩短，批可以开大；视觉 token 极多时，熵排序本身要对每个 token 的注意力分布求熵，排序开销随 token 数增长，批内每条请求的排序阶段无法完全并行掩盖。因此负载配方要求：批调度器应按「视觉 token 数 × 历史长度」的乘积分桶，而不是按请求数分桶。同一批内混入一条超长历史请求，会让整批的熵读取阶段被它拖住。</p>\n<p>代价体现在首 token 延迟上。首 token 延迟由视觉编码、拼接、前若干层熵读取、排序、重建序列五段构成，其中熵读取与排序是这套方法新增的段。批越大，熵读取段的并行度越高但排序段的串行成分越难掩盖；批越小，每轮增量延迟越可控但吞吐下降。SLO 以首 token 延迟与每轮增量延迟为主，预算需按轮次预留额外前向时间——这句话的工程含义是：容量规划时不能只按「一次前向」估延迟，而要按「轮次数 × 每轮一次额外熵读取前向」估总算力占比，轮次越多、上下文越长，这个占比越高。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-22\">二十二 · 并发形态与注意力导出路径</h3>\n<p>并发请求的形态直接决定熵能否被取到。机制要求在 LLM 内部读取文本对视觉 token 的注意力，而生产推理栈普遍使用融合注意力内核（FlashAttention 类），这类内核为省显存不物化完整注意力矩阵。若并发批里所有请求都走融合内核，熵计算就缺少输入，必须额外导出注意力，吞吐下降且实现复杂。这是负载不对时最硬的失败模式：不是精度问题，是路径问题。</p>\n<p>可行的并发配方是分流。对需要熵引导的请求（多轮、视觉证据关键）走导出路径，对单轮、视觉 token 少的请求走融合内核路径不做剪枝。分流比例决定整体吞吐：导出路径的注意力写回带来额外带宽开销，设导出矩阵大小为 $B \\times H \\times S_{\\text{vis}} \\times S_{\\text{txt}}$（批、头数、视觉序列、文本序列），则带宽代价与批大小和文本长度成正比。并发高、文本长时，导出开销会吃掉剪枝省下的算力，此时应降低批大小或缩短参与熵读取的层数。</p>\n<p>具体例子：一个在线服务同时接收单轮图像问答与多轮客服对话。若统一走导出路径，单轮请求白付导出带宽；若统一走融合内核，多轮请求无法剪枝、关键证据在多轮漂移中被误删。正确做法是按请求形态在入口处打标，批调度器把同类请求聚批，避免一个批内混用两种注意力路径导致内核切换。代价是调度复杂度上升，收益是每条路径都工作在它擅长的负载上。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-23\">二十三 · 负载不对时的三种失效</h3>\n<p>第一种失效是历史稀释。多轮对话中历史文本越长，当前轮对视觉 token 的注意力越被旧轮次摊薄，熵分布被旧轮次污染。表现为：本轮真正关键的视觉 token 在当前注意力下熵值不高，被排到 top-k 之外，答案出现物体属性或文字识别错误。这不是排序算法错，是输入分布已经不代表当前意图。缓解手段是按轮重算熵预算并整流归一化，整流后注意力更集中，减少多轮漂移误删，但整流本身不能消除历史长度的绝对影响，只能压低尺度差异。</p>\n<p>第二种失效是预算过激。top-k 按固定比例设置时，遇到细节密集型图像（小字、密集控件、细粒度属性）会剪掉过多 token。熵排序偏好「语义分散、不可替代」的 token，而 OCR 级证据往往集中在少数低熵但高确定性的 token 上——这些 token 的注意力分布尖锐、熵低，恰好被排序排除。负载配方因此要求：细节密集型请求应提高 top-k 比例或直接绕过剪枝，按图像类型而非全局固定比例分配预算。</p>\n<p>第三种失效是路径缺失，即前节所述的融合内核不导出注意力。三种失效的共同点是：它们都不表现为「剪枝比例不够」，而表现为「剪枝依据不可信」。工程判断是，负载不对时不要调 top-k，先检查请求形态是否落在适用边界内——视觉 token 数量中等、多轮对话为主。超出这个边界，熵排序可能保留语义分散但细节不足的 token，规模上限受每轮重算熵的前向开销约束，轮次越多、上下文越长，额外算力占比越高。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-24\">二十四 · 容量规划中的配方表</h3>\n<p>把负载配方落成可执行的容量表，需要三个输入：轮次分布、视觉 token 数分布、并发到达率。下表给出请求形态与配置的对应关系，数值为定性档位而非实测。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>批大小</th><th>top-k 策略</th><th>注意力路径</th><th>主要代价</th></tr></thead><tbody><tr><td>单轮、视觉 token 中等</td><td>大</td><td>固定比例或绕过</td><td>融合内核</td><td>剪枝收益有限</td></tr><tr><td>多轮 2–3 轮、追问同区域</td><td>中</td><td>固定预算</td><td>导出路径</td><td>每轮熵读取前向</td></tr><tr><td>多轮 4 轮以上、追问跳转</td><td>小</td><td>按轮重设</td><td>导出路径</td><td>历史稀释、重算开销</td></tr><tr><td>细节密集型（OCR/属性）</td><td>小</td><td>提高比例或绕过</td><td>融合内核</td><td>证据丢失风险</td></tr></tbody></table>\n<p>表中「按轮重设」的含义是每轮按当前上下文重算熵预算，而不是沿用首轮结果。它的代价是每轮一次额外前向，收益是避免旧轮次污染。容量规划时把这条路径的算力按 $\\sum_r$ 累加，而不是按单次前向乘一个系数。并发到达率高时，小批多路并行优于大批串行，因为熵读取段的延迟对小批更友好。</p>\n<p>KV cache 的规划也要跟着配方走：仅保留压缩后视觉 token 对应的条目，长度随轮次变化。这意味着 KV cache 的显存占用不是常数，而是随 top-k 结果波动的变量，容量规划要按最坏轮次的保留量留余量，否则高并发下会出现显存抖动导致的批重排。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-25\">二十五 · 配方与相邻方法的边界</h3>\n<p>负载配方还承担一个判别职责：什么请求该交给这套方法，什么请求该交给相邻方法。与一次性输入端剪枝不同，它在 LLM 内部用注意力熵而非外部打分器决定保留，因此它要求请求存在可读取的语言侧注意力——单轮短请求里这个信号太弱，交给输入端剪枝更划算。与逐层压缩不同，它不改变层间序列长度而是每轮重设预算，因此它适合轮次驱动的负载，不适合层间结构固定的静态批。与量化感知剪枝不同，它不联合量化误差，只处理注意力未校准与漂移问题，因此量化组合（INT8 视觉分支、INT4 LLM 权重）可以叠加，但量化误差本身不在它的修正范围内。</p>\n<p>部署侧的单卡或双卡 Blackwell 档位、张量并行拓扑、剪枝需与注意力算子同卡，这些约束把配方进一步收紧：剪枝发生在 LLM 内部，跨卡拆分注意力头会让熵读取变成跨卡集合通信，每轮一次，轮次越多通信占比越高。因此多轮负载优先单卡或双卡紧耦合拓扑，而不是把视觉编码器与 LLM 拉开距离。视觉编码器可分离部署，但熵读取必须与注意力同卡，这条边界决定了配方的拓扑上限。</p>\n<p>最终落点是一个工程判断：这套方法的负载配方不是「调参」，而是「选请求」。请求形态落在图像加多轮对话、视觉 token 中等、每轮追问可追踪的区间内，熵引导剪枝的收益稳定；一旦请求变成单轮、超长历史或细节密集型，机制的依据就从「注意力熵反映证据分布」退化为「注意力熵反映历史噪声」，此时正确的动作是切走负载，而不是在错误的分布上继续调 top-k。</p>\n<h3 id=\"alg-era-entropy-prune-sec-26\">二十六 · 硬件档位与视觉编码器/LLM 的分离部署</h3>\n<p>熵引导视觉剪枝的部署起点不是“买多大的卡”，而是把视觉编码器与语言模型在物理上拆开。机制上，剪枝所需的注意力读取发生在 LLM 前若干层内部，视觉编码器只负责把图像变成 token 序列，二者对算力的需求形态完全不同：编码器是短时高密度的卷积/注意力爆发，LLM 是长时、受 KV cache 带宽约束的自回归解码。把两者塞进同一张卡会互相争抢 SM 与显存带宽，尤其在多轮对话中编码器每轮可能被重复调用。工程上更稳的做法是单卡 Blackwell 上做进程级分离（编码器用独立 CUDA stream 与显存池），或双卡 Blackwell 上做物理分离，编码器卡与 LLM 卡之间通过 NVLink 传视觉 token 张量。代价是跨卡传输一次视觉 token 张量带来的延迟，量级取决于 token 数与隐藏维；对中等视觉 token 规模，这笔传输远小于在 LLM 卡上重跑编码器的开销。</p>\n<p>档位选择的判断依据是“每轮重算熵的额外前向”占端到端延迟的比例。单卡档适合视觉 token 中等、轮次少、SLO 以首 token 延迟为主的场景；双卡档适合长多轮、批内混合图像请求、需要把编码器与解码器流水重叠的场景。一个具体例子：GB200 NVL72 机架内，把视觉编码器固定在少数几颗 GPU 上做共享池，LLM 实例按张量并行铺开，剪枝逻辑随 LLM 走，编码器池按请求到达率弹性扩缩——这样熵重算的开销只落在 LLM 侧，不会因为编码器排队而被放大。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-27\">二十七 · 并行拓扑：剪枝必须与注意力算子同卡</h3>\n<p>剪枝发生在 LLM 内部，读取的是文本位置对视觉 token 的注意力分布，因此熵计算所在的设备必须能直接看到注意力张量。这决定了一条硬约束：张量并行（TP）是主拓扑，剪枝逻辑与注意力算子同卡同 rank，不能把熵计算下放到单独的“剪枝服务”。若用流水并行（PP），承载前若干层的 stage 负责取熵与重建序列，后续 stage 接收的是已压缩的序列，跨 stage 传的是压缩后的激活而非原始视觉 token，这能省带宽但要求 stage 切分点落在剪枝层之后。伪代码思路如下：</p>\n<div class=\"formula\">$$H_i=-\\sum_{j}p_i(j)\\log p_i(j),\\quad s_i=\\frac{H_i}{\\sum_k H_k},\\quad \\text{keep}=\\text{TopK}(s_i)$$</div>\n<p>在 TP 组内，每个 rank 持有注意力头的一个切片，熵需要对每个视觉 token 收到的全部文本位置注意力求和，因此要么在 TP 组内做一次 all-reduce 把各头分布拼起来，要么按头分别算熵再归并排序。前者通信量正比于“视觉 token 数 × 文本长度”，后者通信量正比于“视觉 token 数 × 头数”，后者更省但排序结果需再做一次跨 rank 的 top-k 归并。系统代价上，这次集合通信落在每轮解码的关键路径上，是剪枝方案相对普通解码多出来的固定延迟项；视觉 token 越多、历史越长，这一项越显著。工程判断是：把剪枝层尽量前移（前若干层即取熵），让压缩后的序列承担后续所有层的计算与 KV 写入，用一次通信换整段序列变短，净收益为正。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-28\">二十八 · 量化方案：INT8 视觉分支 + INT4 LLM 权重的组合边界</h3>\n<p>量化与熵剪枝是正交的两件事，但叠在一起时有顺序问题。视觉编码器分支用 INT8 是安全的：编码器输出的是 token 特征，量化误差在特征层面被后续注意力与熵排序吸收，且编码器不在剪枝关键路径上。LLM 权重用 INT4 则要小心——熵是从注意力分布算出来的，而 INT4 权重量化会改变注意力的数值分布，尤其是低概率尾部。若熵排序在量化后的注意力上做，尾部被量化抹平会让原本“证据分散”的高熵 token 被打成低熵，误剪风险上升。可行做法是：在剪枝层用较高精度（如 FP8 或保留注意力 softmax 的 FP16 累加）导出注意力用于熵计算，其余层走 INT4 权重；或者先剪枝、后量化，把量化校准放在压缩后的序列上做。</p>\n<p>代价体现在两处：一是混合精度让剪枝层无法完全吃满 INT4 的带宽收益，该层显存带宽占用高于纯 INT4 路径；二是若为取熵额外保留一份 FP16 注意力导出缓冲，显存峰值上升，批大小受限。具体例子：一个图像加多轮文本的请求，视觉 token 中等规模，INT4 LLM 权重下 KV cache 是显存主项，此时把剪枝层的注意力导出缓冲控制在单层单次前向的规模、用完即释放，比常驻一份全序列注意力矩阵更现实。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-29\">二十九 · KV 策略：只保留压缩后视觉 token 的条目</h3>\n<p>剪枝的直接收益要落到 KV cache 上才算数。机制上，视觉 token 被 top-k 保留后，重建的序列只含保留的视觉 token 与全部文本 token，KV cache 应按重建后的序列分配：被剪掉的视觉 token 不写 KV、不占槽位。多轮对话中这一点尤其关键——每轮按当前上下文重算熵预算，保留集合随轮次变化，KV cache 的视觉段长度是逐轮变动的，不能按首轮长度静态预留。工程实现上需要把视觉段的 KV 槽位做成可重映射的逻辑段，每轮剪枝后把保留 token 的 KV 条目按新顺序紧凑排列，释放被剪条目的槽位给后续轮次或同批其他请求。</p>\n<p>代价是重排本身要搬动 KV 数据，搬运量正比于保留 token 数 × 每 token KV 字节数，且发生在每轮解码前，属于增量延迟。若用分页式 KV 管理（逻辑块到物理块的映射表），重排退化为改映射表而非搬数据，代价降到可忽略，但要求注意力内核支持非连续块寻址。一个具体例子：长多轮会话里历史文本很长，视觉段被压缩后只占 KV 的小部分，此时把释放出的槽位让给历史文本的 KV 更划算；反之细节密集型图像保留比例高，视觉段仍是 KV 主项，压缩收益直接体现为可支撑更大批大小。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-30\">三十 · 调度参数：按轮次预留熵重算的前向预算</h3>\n<p>调度层要把“每轮重算熵”当成一个显式的成本项排进时间线，而不是当作解码的免费副产品。参数上至少有三个旋钮：剪枝层位置（越前越省后续计算，但注意力尚未校准，熵估计噪声大）、top-k 比例（按轮次与图像类型动态给，而非全局固定）、每轮熵重算的预算上限（超过则退化为沿用上一轮保留集合）。SLO 以首 token 延迟与每轮增量延迟为主，首 token 延迟里包含编码器前向加剪枝层前向，增量延迟里包含熵重算加 KV 重排。连续批处理下，剪枝请求与不剪枝请求混批会让批内序列长度参差，调度器应按“压缩后长度”而非“原始长度”做分桶，否则长序列请求拖累整批。</p>\n<p>具体配置思路可复现为：单卡或双卡 Blackwell，编码器与 LLM 分离部署；TP 为主拓扑，剪枝逻辑与注意力同卡，剪枝层取前若干层并在 TP 组内归并 top-k；视觉分支 INT8、LLM 权重 INT4、剪枝层注意力以较高精度导出；KV 按压缩后序列分页管理、视觉段逐轮重映射；调度上按压缩后长度分桶、按轮次预留熵重算预算、top-k 比例随轮次与图像细节密度调整。失败模式要提前埋检测：融合注意力内核不导出注意力矩阵时熵无法计算，需保留一条非融合导出路径，吞吐下降且实现复杂；历史过长使熵被旧轮次稀释时，应只取当前轮文本位置对视觉 token 的注意力做熵，而非全历史平均；top-k 过激在细节问答上丢证据时，用答案中物体属性或文字识别错误率做回归哨兵，触发比例回调。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-31\">三十一 · 熵预算的边界条件与部署代价</h3>\n<p>这套配方的可复现性不取决于参数抄得多准，而取决于能否识别它失效的边界。熵排序的本质是“跨模态证据的分散度”，因此它对视觉 token 的绝对数量不敏感，却对注意力分布的<em>校准状态</em>极度敏感。整流归一化 $s_i=H_i/\\sum_k H_k$ 只是把尺度差异压平，并不能修复注意力本身被旧轮次污染的问题。多轮场景下，历史文本越长，当前轮对视觉 token 的注意力被稀释得越厉害，$p_i(j)$ 中来自旧轮次的权重占比上升，$H_i$ 的估计就偏离本轮真实证据分布。工程上的判断线是：当历史 token 数与当前轮 token 数的比值超过某个量级，熵预算必须按轮次重设而非沿用固定比例，否则剪枝决策会系统性地偏向语义泛化、丢掉细节证据。这不是精度问题，是分布漂移问题，调 top-k 比例救不回来。</p>\n<p>部署拓扑上有一个硬约束容易被忽略：剪枝发生在 LLM 内部前若干层，读取的是文本对视觉 token 的注意力，因此剪枝逻辑必须与注意力算子同卡，不能把视觉编码器与 LLM 的分离部署延伸到剪枝环节。视觉编码器可以独立成卡（INT8 视觉分支），LLM 权重走 INT4，张量并行是主拓扑，但熵计算点必须落在持有注意力输出的那个 rank 上。若推理栈使用融合注意力内核且不导出注意力矩阵，熵无法计算，必须额外开一条导出路径——这是吞吐的直接代价：融合内核的优势被部分抵消，且导出缓冲带来额外显存占用。可复现的配置思路是把导出路径做成可选分支，在 SLO 允许的延迟预算内按需开启，而不是默认全量导出。</p>\n<div class=\"formula\">$$\\text{cost}_{\\text{round}}=T_{\\text{prefill}}+T_{\\text{entropy}}(L_{\\text{hist}}+L_{\\text{vis}})+T_{\\text{decode}},\\quad \\text{budget}_k=\\text{TopK}(H_i^{(r)})$$</div>\n<p>每轮重算熵的额外前向开销随历史长度线性增长，这是规模上限的真正来源，而非视觉 token 数量。首 token 延迟与每轮增量延迟是主 SLO，预算需按轮次预留额外前向时间；长多轮会话宜用小批，因为批大小同时受视觉 token 数与历史长度约束，两者叠加会把单卡显存推到 KV cache 的边界。KV 策略只保留压缩后视觉 token 对应的条目，长度随轮次变化，这意味着 KV cache 的分配不能按固定上限预分，否则压缩后的空洞会浪费带宽。失效模式里最隐蔽的是 top-k 过激：固定比例预算遇到细节密集型图像（OCR 级证据）会剪掉过多 token，答案出现属性或文字识别错误，此时熵排序保留的往往是语义分散但细节不足的 token——这是熵度量本身的盲区，只能靠按图像类型动态调预算来兜底，而非靠提高 k。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>系统表现</th><th>工程处置</th></tr></thead><tbody><tr><td>融合内核不导出注意力</td><td>吞吐下降、实现复杂</td><td>导出路径做成可选分支</td></tr><tr><td>历史稀释当前轮注意力</td><td>关键证据被误判低熵</td><td>按轮次重设熵预算</td></tr><tr><td>细节密集型图像 + 固定 k</td><td>OCR/属性错误</td><td>按图像类型调预算</td></tr></tbody></table>\n<h3 id=\"alg-era-entropy-prune-sec-32\">三十二 · 熵预算的显存账：KV cache 长度随轮次浮动</h3>\n<p>熵引导剪枝在显存侧最直接的结果，是把视觉 token 的 KV cache 从“一次性分配、整段常驻”改成“按轮次重设、长度浮动”。机制上，剪枝发生在 LLM 前若干层读取文本对视觉 token 的注意力之后，重建压缩序列时只保留 top-k 视觉 token 对应的位置，因此 KV cache 中视觉部分的条目数等于当轮预算 k，而非编码器输出的原始视觉 token 数。代价是分配器必须支持变长视觉段：同一请求在第 n 轮与第 n+1 轮的视觉 KV 长度不同，若沿用按最大长度预留的静态池，显存占用由峰值轮次决定，压缩带来的节省被抵消。</p>\n<p>把账算清楚：设原始视觉 token 数为 V，每 token 每层 KV 占 2·d·b 字节（d 为头维乘层数，b 为每元素字节），层数 L，则未压缩视觉 KV 为 2·V·L·d·b；压缩后为 2·k·L·d·b，节省比例 (V−k)/V。多轮场景下历史文本 KV 随轮次线性增长，视觉 KV 却被压到 k，于是视觉占比随轮次下降——这正是显存先崩的位置从视觉段转移到历史文本段的原因。工程判断：预算 k 不应按固定比例设，而应按“当前轮可用显存余量 ÷ 每 token KV 字节”反推上限，再与熵排序结果取交集。</p>\n<p>具体例子：一个携带长历史的多轮图文会话，视觉编码器输出数百级 token，前几轮 k 取较大值保证证据完整；到第五、六轮历史文本 KV 已占主导，若仍按首轮比例保留视觉 token，单请求显存超池触发抢占，尾延迟立刻恶化。此时把 k 下调并配合小批，比提高批大小更能稳住 SLO。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-33\">三十三 · 带宽与注意力导出的隐藏税</h3>\n<p>熵计算要求读取文本对视觉 token 的注意力分布 p_i(j)，而 FlashAttention 类融合内核在前向中不落地完整注意力矩阵。要取熵，必须在指定层插入导出路径：要么分块重算注意力分数并即时归约，要么让内核在特定层回退到非融合实现。无论哪种，代价都是额外的片上与 HBM 带宽往返——注意力矩阵尺寸为文本长度 × 视觉 token 数，导出即意味着把这部分中间量写回或至少跨 SM 归约。</p>\n<div class=\"formula\">$$H_i=-\\sum_{j}p_i(j)\\log p_i(j),\\quad \\text{keep}=\\text{TopK}(H_i)$$</div>\n<p>注意熵是对 j 求和后的标量，因此理想实现是“分块计算 p_i(j)、块内累加 −p log p、不落地整矩阵”，把带宽代价压到与一次额外注意力前向同阶，而不是与矩阵元素数同阶。若实现偷懒先写矩阵再归约，带宽开销会随文本长度与视觉 token 数乘积增长，在长上下文多轮请求上直接吃掉剪枝省下的算力。</p>\n<p>吞吐侧的账：导出路径只在剪枝层触发，属于每轮一次的前向附加开销，摊到 decode 阶段可忽略，但摊到首 token 延迟上不可忽略——首 token 路径包含预填与熵计算两段串行。工程上应把熵计算与预填的注意力计算合并到同一遍，避免二次读 KV；否则预填带宽翻倍，首 token 延迟按预填占比上升。具体例子：视觉 token 中等、文本历史较长的请求，若导出实现走“先落地再归约”，预填阶段 HBM 读写量显著高于融合路径，首 token 延迟被拉长，而 decode 阶段几乎无感——这决定了该机制更适合把代价记在 TTFT 预算而非 TPOT 预算上。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-34\">三十四 · 通信：剪枝点与并行拓扑的耦合</h3>\n<p>剪枝发生在 LLM 内部，必须与注意力算子同卡，因此它天然与张量并行的切分方式耦合。张量并行下，注意力头被切到多卡，每个视觉 token 的注意力分布 p_i(j) 分散在各卡的头上；求 H_i 需要对头维做跨卡归约，top-k 选择又要求全局排序。这带来一次 all-reduce（熵和）加一次跨卡 top-k（可用两次 all-reduce 或一次 all-gather 后本地选），通信量正比于视觉 token 数而非文本长度，量级可控但延迟敏感——它落在每轮解码的关键路径上。</p>\n<p>流水并行下问题更尖锐：剪枝层位于前若干层，若这些层落在不同 stage，熵必须在 stage 间传递，重建压缩序列又要求下游 stage 接受变长输入，micro-batch 的形状在流水中间发生变化，气泡与重排成本上升。工程判断：把剪枝层约束在单个 stage 内，或至少在同一个张量并行组内完成熵归约与 top-k，避免跨 stage 的变长同步。具体例子：双卡张量并行部署、视觉编码器与 LLM 分离时，剪枝层所在卡的 all-reduce 与视觉编码器到 LLM 的激活传输可能重叠；若调度器不区分优先级，每轮重算熵的集合通信会与视觉特征搬运争抢链路，尾延迟出现毛刺。</p>\n<p>规模上去以后通信先崩的判据：当每轮熵归约的固定延迟开始与单 token decode 时间同量级，增加批大小不再提升吞吐，因为关键路径被集合通信占据。此时应改为单卡内完成剪枝、跨卡只同步压缩后的序列长度，把通信从“每 token 分布”降为“每请求一个标量”。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-35\">三十五 · 功耗与算力占比：重算熵的边际成本</h3>\n<p>每轮重算熵意味着每轮一次额外前向：读取剪枝层注意力、归约、排序。其算力占比随轮次与上下文长度上升——历史越长，注意力计算本身越贵，熵归约的绝对开销也越大，但相对占比取决于剪枝层数占总层数的比例。设剪枝层数为 m、总层数 L，则额外前向约占 m/L 的预填算力；多轮累计后，这部分算力不再是一次性摊销，而是每轮复利。</p>\n<p>功耗侧的表现是“峰值不降、均值上升”：剪枝减少了后续层的视觉 token 数，decode 阶段每步的注意力与 FFN 计算量下降，功耗均值下降；但每轮开头的熵计算是一次短时高占用脉冲，SM 占用率与 HBM 带宽瞬时拉满，对功耗封顶敏感的整机柜部署而言，这个脉冲决定了功率预算的上限而非均值。工程上可用“隔轮重算”折中：仅在检测到注意力分布漂移超过整流后阈值时重算熵，其余轮次沿用上轮预算，把脉冲频率降下来。</p>\n<p>具体例子：NVL72 级部署中单卡功耗封顶固定，若每轮熵脉冲与视觉编码器编码重叠，瞬时功耗叠加触发降频，decode 抖动。把视觉编码器与 LLM 的调度错开、或把熵计算挪到编码器空闲窗口，能消掉这类毛刺。规模上限因此不在单请求算力，而在“每轮脉冲 × 并发请求数”是否越过功率墙。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-36\">三十六 · 尾延迟：多轮漂移下的预算抖动</h3>\n<p>尾延迟的来源不是均值开销，而是预算抖动。熵排序本身对注意力尺度不敏感，整流归一化 s_i=H_i/ΣH_k 抑制了尺度差异，但多轮历史过长会使熵估计被旧轮次稀释：当前轮对视觉 token 的注意力被历史文本摊薄，H_i 分布整体偏移，top-k 边界上的 token 在相邻轮次间反复进出保留集。每次进出都改变压缩序列长度，进而改变 KV cache 形状与后续层的计算图，连续批处理中这类形状变化会触发重排与填充，尾请求的增量延迟被放大。</p>\n<p>机制上的缓解是给 top-k 加滞回：对已保留 token 的熵打分加一个小偏置，只有新 token 显著超过才替换，减少边界抖动；同时按轮次重设预算时对 k 做平滑，避免单轮骤降。代价是滞回偏置引入少量保守性，压缩率略降，但尾延迟方差显著收窄。失败模式明确：top-k 过激在细节密集型图像上丢证据，表现为物体属性或文字识别错误——这类错误在尾请求上更难被批内平均掩盖，因为尾请求往往正是长历史、细节多的那类。</p>\n<p>具体例子：同一批内混合短会话与长多轮会话，短会话的视觉 KV 压缩率高、decode 快，长会话因历史稀释导致 k 抖动、KV 形状频繁变化，批内最慢请求决定整批完成时间。调度器若按请求历史长度分桶、对长会话单独小批并预留熵计算时间，尾延迟可控；若混批，则尾延迟由最长会话的预算抖动主导。规模上去以后先崩的次序由此清晰：显存（历史文本 KV 先于视觉 KV 触顶）→ 通信（每轮熵归约进入关键路径）→ 功耗（熵脉冲叠加并发）→ 尾延迟（预算抖动与形状重排），而带宽导出税贯穿始终，是决定这套机制能否落地的第一道门槛。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-37\">三十七 · 熵预算撞上系统墙：先崩的是注意力导出与轮次重算</h3>\n<p>把熵引导剪枝放进真实推理栈，第一个失效点不在算法而在内核边界。熵需要每个视觉 token 收到的文本侧注意力分布 $p_i(j)$，而生产环境普遍使用融合注意力内核，前向只回传输出张量、不回传归一化后的打分矩阵。要取熵就得在 LLM 前若干层插入导出路径：把 $p_i(j)$ 落成显存中的临时张量再归约。代价是双份的——注意力矩阵本身按 $O(L_t \\cdot L_v)$ 增长，导出即多一次写带宽；归约又要读回，等于把本已被融合省掉的中间流量重新打开。以单卡 Blackwell 为例，视觉 token 数千、文本历史数千时，这个临时张量的体量与一次全序列注意力的中间结果同阶，HBM 带宽成为第一道瓶颈，而非算力。工程上可行的折中是只在少数层、只对视觉列做局部导出，用分块归约把熵算在寄存器/共享内存侧，避免整矩阵落地；但这要求剪枝逻辑与注意力算子同卡同核，跨卡切分张量并行时视觉列被切开，熵需跨卡归约，通信量随 TP 度线性上升。</p>\n<p>第二道墙是轮次重算的算力占比。每轮按当前上下文重设预算，意味着每轮都要一次额外前向用于取熵，其增量延迟可写成</p>\n<div class=\"formula\">$$\\Delta T_{\\text{turn}} \\approx \\frac{L_t L_v d}{F_{\\text{eff}}} + \\frac{L_t L_v}{B_{\\text{hbm}}}$$</div>\n<p>前者是打分与归约的算力项，后者是导出/读回的带宽项；两者都随历史长度 $L_t$ 线性增长，而真正用于解码的 token 数并不增长。于是轮次越多、上下文越长，额外前向在每轮总时延中的占比越高，尾延迟被这段固定开销钉住：批内只要有一个长历史会话，整个批的 P99 增量延迟就被它拖住。批大小因此受视觉 token 数与历史长度共同约束，长多轮会话只能小批跑，吞吐换尾延迟。规模上去后先崩的顺序通常是：融合内核不导出注意力→被迫加导出路径→HBM 带宽与 TP 跨卡归约先饱和→再叠加轮次重算使尾延迟不可控。</p>\n<p>第三类是剪枝本身带来的质量-规模耦合失效。top-k 按固定比例设置时，细节密集型图像（表格、票据、密集文字）会被过度剪除，答案出现属性或 OCR 级错误；而视觉 token 极多时，熵排序倾向保留语义分散、证据面广的 token，恰恰丢掉承载细粒度证据的低熵 token。多轮场景更隐蔽：历史文本稀释当前轮对视觉 token 的注意力，熵分布被旧轮次污染，本轮关键证据被判为低熵而剪掉，且这种误删在 KV cache 上不可逆——压缩后视觉 token 对应的条目已按剪枝结果写入，后续轮次无法找回。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先饱和的资源</th><th>表现</th></tr></thead><tbody><tr><td>视觉 token 数↑</td><td>HBM 带宽（注意力导出）</td><td>熵归约等待，首 token 延迟抬升</td></tr><tr><td>历史轮次↑</td><td>额外前向算力</td><td>每轮增量延迟固定开销占比升高，P99 恶化</td></tr><tr><td>TP 度↑</td><td>跨卡归约通信</td><td>视觉列切分后熵需 all-reduce，NVLink 流量上升</td></tr><tr><td>批大小↑</td><td>KV cache 显存</td><td>压缩后长度随轮次变化，批内碎片化</td></tr></tbody></table>\n<p>因此这套方案的适用边界是视觉 token 中等、以多轮对话为主、且推理栈能低成本暴露视觉列注意力的场景；一旦进入密集文档或超长会话，应把固定 top-k 改为按图像复杂度与轮次动态分配预算，并把熵计算限制在首轮或证据变化轮，用缓存复用换取尾延迟稳定。</p>\n<h3 id=\"alg-era-entropy-prune-sec-38\">三十八 · 熵取不到：融合内核下的可观测性缺口</h3>\n<p>熵引导剪枝的第一道失败不是精度，而是<strong>根本拿不到熵</strong>。机制要求读取 LLM 前若干层中文本位置对视觉 token 的注意力分布 $p_i(j)$，再算 $H_i=-\\sum_{j}p_i(j)\\log p_i(j)$。但生产推理栈默认走 FlashAttention 类融合内核：注意力在 SRAM 里分块算出、立即被 softmax 与 PV 乘吸收，中间矩阵从不落回 HBM。融合正是吞吐的来源，也正是熵的来源被切断的地方。</p>\n<p>工程上只有三条路，代价各不相同。其一，在指定前若干层把注意力内核换成非融合版本，显式物化 $[L_{\\text{vis}} \\times L_{\\text{text}}]$ 的注意力块——以视觉 token 数千、文本数百计，这块矩阵的体量足以把原本被融合省掉的 HBM 写回重新加回来，prefill 阶段的有效带宽被摊薄，首 token 延迟直接抬升。其二，在融合内核里加旁路，用在线 softmax 的 running max 与 running sum 顺手累积每列的熵估计，避免全矩阵物化，但需要改内核、改归约顺序，且分块顺序会影响熵的数值稳定性。其三，把熵计算挪到独立的轻量打分头上，用少量层的小规模注意力近似，代价是打分与真实注意力分布脱钩，剪枝决策的依据变弱。</p>\n<p>诊断信号很直接：在 profiling 里对比开启与关闭熵导出的 prefill 耗时，若差异集中在 attention kernel 的 HBM 读写而非计算，说明物化路径生效；若 attention kernel 时间不变而总时间上升，说明旁路累积引入了额外同步。监控上应把“熵导出路径是否命中”做成启动期自检——检测当前 attention backend 是否声明支持返回 attention weights，不支持则拒绝启用剪枝，而不是静默退化为不剪枝。后者最危险：配置写着 top-k 保留，实际全量 token 进解码，KV cache 与延迟预算全部失配。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-39\">三十九 · 多轮稀释：熵分布被旧轮次污染</h3>\n<p>多轮对话是这套机制的主场，也是它最典型的精度塌陷点。每轮重算熵时，注意力分布的归一化分母覆盖的是<em>全部历史文本位置</em>。历史越长，旧轮次的文本 token 分走的注意力质量越多，当前轮对视觉 token 的注意力被稀释，$H_i$ 被压平——原本高度集中、指向关键视觉证据的分布，被摊成接近均匀的低熵形态，于是排序把真正的证据排到 top-k 之外。</p>\n<p>这与“注意力未校准”是两类不同的病：前者是打分器本身不准，后者是打分器准但输入被污染。区分二者的诊断手段是看熵的<strong>轮间轨迹</strong>：对同一批视觉 token 记录每轮的 $H_i$ 与整流后的 $s_i=H_i/\\sum_k H_k$，正常情形下关键证据 token 的 $s_i$ 应在轮间保持高位或随新问题上升；若观察到全体视觉 token 的 $s_i$ 随历史长度单调趋平、方差收缩，即为稀释型污染。此时答案的表现不是完全无依据，而是“依据错位”——引用了图里存在但与本轮问题无关的区域。</p>\n<p>缓解要在预算侧做，而不是在熵公式侧硬改。按轮次重设预算的含义是：top-k 的 $k$ 与熵的统计窗口都随轮次调整，近期轮次的文本位置在归一化中占更高权重，或对历史位置做长度归一化后再求分布。代价是每轮一次额外前向用于重算熵，轮次越多、上下文越长，这部分开销在端到端延迟中的占比越高；对小批长会话，这笔开销可能吞掉剪枝省下的解码时间。工程判断是：当历史长度超过某个由显存与 SLO 共同决定的门槛时，改用滑动窗口截断历史再算熵，牺牲少量上下文一致性换取熵估计的可信度。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-40\">四十 · 预算过激：细节密集型图像的静默错误</h3>\n<p>固定比例 top-k 是最容易埋雷的配置。熵排序偏好“证据分散、不可替代”的 token，这在语义问答上表现良好；但遇到细节密集型图像——小字、密集表格、物体属性细粒度区分——真正承载答案的往往是少数几个局部 token，它们的注意力分布可能并不分散，熵值不高，于是被固定比例一刀切掉。结果不是崩溃，而是物体属性答错、文字识别漏字，属于最难在监控里捕获的静默精度退化。</p>\n<p>诊断要建立<strong>按图像类型的分层指标</strong>，而不是只看总体准确率。把评测集按“文本密度”“目标数量”“属性细粒度”切片，分别统计剪枝前后的答案一致率；若总体掉点很小但文本密集切片掉点显著，即定位为预算过激而非机制失效。在线侧可用一个廉价代理信号：解码阶段对视觉 token 的累计注意力质量，若压缩后序列中视觉 token 获得的注意力远低于压缩前同位置 token，说明保留下来的 token 并非解码真正需要的。</p>\n<p>回滚策略应是<strong>分级而非开关式</strong>。第一级，把固定比例 top-k 改为按熵分布自适应定 $k$——当 $s_i$ 的分布尾部厚重（大量 token 熵接近）时放宽预算；第二级，对判定为细节密集的请求直接跳过剪枝，走全量视觉 token，代价是这一路请求的 KV cache 与 prefill 时间上升，需要容量规划里预留这部分超额；第三级才是全局关闭剪枝。分级的意义在于把精度事故限制在少数请求上，而不是让一次坏样本触发全集群的吞吐回退。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-41\">四十一 · 批抖动与路由不均：压缩率异质带来的尾延迟</h3>\n<p>剪枝后的序列长度不再由输入决定，而由每张图的熵分布决定。同一批里，简单图的压缩后视觉 token 可能只有复杂图的几分之一，于是批内序列长度高度异质。连续批处理按 token 预算调度时，这种异质会直接转化为<strong>批抖动</strong>：新请求不断挤入、已完成序列释放，批的组成每步都在变，step 时间方差放大，尾延迟尖刺出现在“长压缩序列 + 新短请求混编”的时刻。</p>\n<p>更隐蔽的是路由不均。若服务按请求哈希或轮询把请求分到不同副本，而各副本的剪枝配置、熵导出路径、量化组合不一致，则同一类图像在不同副本上得到不同的压缩率与不同的答案质量，表现为“同一问题重试一次答案变了”。诊断需要两个维度：按副本统计压缩后 token 长度的分布，若副本间分布显著偏移即为配置漂移；按时间窗口统计 P99 step 时间与批内序列长度极差的相关性，相关性高即确认抖动来自异质批。</p>\n<p>工程手段有三条。其一，在调度层引入<strong>长度感知的准入</strong>，把压缩后长度接近的请求聚到同一批，代价是等待窗口变长、小批利用率下降。其二，为剪枝请求与全量请求设不同队列与不同 token 预算，避免细节密集请求的超长序列拖累整批。其三，把压缩后长度作为显式元数据写进请求，让 KV cache 分配按实际长度而非最坏长度预留——这一步同时缓解下一节的 OOM。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-42\">四十二 · OOM 与显存账本：KV cache 长度随轮次漂移</h3>\n<p>这套机制的一个结构性特点是 KV cache 只保留压缩后视觉 token 对应的条目，长度随轮次变化。好处是显存占用下降，坏处是<strong>显存账本不再可静态推算</strong>。多轮会话中，每轮重算熵可能改变保留集合，历史轮次已写入的 KV 条目与新预算不匹配，若实现选择保留旧条目并在新轮追加，视觉部分的 KV 长度会随轮次单调增长而非收敛；若实现选择重写历史 KV，则每轮触发一次视觉段的重计算，prefill 开销按轮次累加。</p>\n<p>OOM 的典型触发不是单请求超限，而是<strong>批内多请求的视觉 KV 同时处于高位</strong>：长多轮会话宜用小批，正是因为每个会话的视觉 KV 长度不可预测且随轮次增长。诊断应把显存拆成三块分别监控——权重、视觉 KV、文本 KV——并记录每块的峰值与请求维度的贡献。若 OOM 前视觉 KV 的增速明显快于文本 KV，说明预算重设逻辑没有真正收敛保留集合。</p>\n<p>回滚与防护要在分配侧做硬约束：为视觉 KV 设每请求上限，超过则强制触发一次全量重算并压缩到预算内，把不可预测的增长转成可预测的周期性开销；在准入侧按当前显存余量而非按请求数限流，因为同请求数下视觉 KV 占用可以差出一个量级。功耗维度上，周期性重算会把 GPU 从解码的低占用态拉回高占用态，能效曲线出现锯齿，容量规划需按最坏轮次而非平均轮次预留。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-43\">四十三 · 监控面与回滚编排</h3>\n<p>把上述失败模式收敛成一套可运维的监控面，需要四个层次的信号同时在线。<strong>机制层</strong>：熵导出路径命中率、每轮 $H_i$ 的均值与方差、整流后 $s_i$ 的尾部厚度——方差收缩是稀释型污染的早期信号。<strong>精度层</strong>：按图像类型切片的答案一致率、视觉 token 在解码中的注意力质量占比——后者是预算过激的在线代理。<strong>性能层</strong>：prefill 与 decode 的 P50/P99、批内序列长度极差、每副本压缩率分布——极差与分布偏移分别对应抖动与路由不均。<strong>资源层</strong>：视觉 KV 峰值、增速、每请求上限触发次数——增速异常先于 OOM 出现。</p>\n<p>回滚必须是<strong>按请求粒度可降级</strong>的编排，而不是全局开关。判定逻辑可以写成：当某请求的熵方差低于阈值且历史长度超门槛，标记为稀释风险，本轮跳过剪枝；当图像被分类为细节密集，直接走全量路径；当副本级压缩率分布偏移超过容忍带，摘除该副本的剪枝配置并重放流量校验。每一级降级都对应明确的代价科目——跳过剪枝意味着该请求的 prefill 时间与视觉 KV 占用回到全量水平，容量规划里必须为这部分“降级配额”留出余量，否则精度保护会以 OOM 的形式反噬。</p>\n<p>最后落在工程判断上：这套机制的失败几乎都不是公式错，而是<strong>可观测性与预算纪律</strong>的问题。熵公式对注意力尺度不敏感、跨模型迁移性好，这些优点只在能稳定取到注意力、且预算随轮次与图像类型自适应时才成立。把“能否取熵”做成启动期硬校验、把“压缩后长度”做成请求级元数据、把“降级配额”写进容量模型，三件事做完，剩下的失败模式才谈得上被监控捕获而不是被用户发现。</p>\n<h3 id=\"alg-era-entropy-prune-sec-44\">四十四 · 同族算法的选择轴：谁在读注意力，谁在改序列</h3>\n<p>把熵引导视觉剪枝放回同族里看，先要问的不是“哪个更准”，而是“决策信号从哪里来、序列长度在什么粒度上被改写”。同族算法大致分成三条线：输入端一次性打分（外部打分器或视觉编码器侧显著性）、LLM 内部逐层压缩（层间序列长度递减）、以及量化/近似误差联合决策。熵引导属于第二条线的一个特殊变体——它在 LLM 内部读注意力，但不改层间长度，而是每轮重设预算。这个定位决定了它与相邻算法的互斥关系：凡是不暴露注意力矩阵的推理栈，它就无法落地；凡是需要细粒度 OCR 证据的场景，它的熵排序会系统性偏向语义分散的 token。</p>\n<p>选择轴可以形式化为两个维度。第一维是信号来源的可观测性：外部打分器可以在视觉编码器输出上直接算，代价是额外一次前向；注意力熵必须在 LLM 前若干层内读取，代价是与 FlashAttention 融合内核的耦合。第二维是预算的时间粒度：一次性剪枝的预算在请求入口固定，逐层压缩的预算随层深变化，熵引导的预算随对话轮次变化。两维交叉后，只有“注意力可观测 + 多轮漂移显著”这个象限是熵引导的独占区，其余象限都应让给邻居算法。</p>\n<div class=\"formula\">$$\\text{select}=\\arg\\max_{a\\in\\mathcal{A}}\\ \\frac{\\text{证据保真度}(a)}{\\lambda\\cdot\\text{每轮增量延迟}(a)+\\mu\\cdot\\text{实现耦合度}(a)}$$</div>\n<p>这里的证据保真度不是精度指标，而是“关键视觉证据在被剪后仍可被语言侧检索到”的概率。分母两项对应两类系统代价：每轮增量延迟决定 SLO 能否守住，实现耦合度决定工程上要改多少内核。熵引导的分母偏大——它要在每轮重算熵，且需要注意力导出路径，因此在单轮、短上下文、注意力不可观测的负载里，它的性价比被一次性剪枝压过。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-45\">四十五 · 与一次性输入端剪枝的对照：漂移是否真的存在</h3>\n<p>一次性输入端剪枝在请求进入 LLM 之前就定下保留集合，之后所有轮次复用同一集合。它的优势是零额外前向、与任何注意力内核解耦、批调度简单。劣势正是熵引导要解决的问题：跨模态注意力未校准时的误删，以及多轮中注意力分布漂移。判断该用哪一个，只需要看一个可观测的量——同一张图在不同轮次下，语言侧对视觉 token 的注意力排序是否稳定。若排序在前两轮内基本不变，一次性剪枝足够；若排序随轮次明显重排，固定集合必然在某轮丢掉当时的关键证据。</p>\n<p>工程上可以用一个低成本探针来判定：在服务里对同一会话的前若干轮记录注意力熵的 top-k 集合交集大小。交集大说明漂移弱，交集小说明漂移强。这个探针本身就要读注意力，所以它只在已经具备注意力导出能力的栈里可行；若栈本身不导出注意力，就只能靠离线采样估计，而这会引入部署配方上的额外分支。</p>\n<ul>\n<li>机制差异：一次性剪枝用外部打分器或编码器显著性，熵引导用 LLM 内部注意力分布的熵并做整流归一化。</li>\n<li>代价差异：一次性剪枝零额外前向，熵引导每轮多一次前若干层的前向与熵计算，长会话下这部分算力占比随轮次线性上升。</li>\n<li>例子：客服多轮问答中，用户第一轮问“图里有什么”，第三轮追问“左下角标签写的什么”。固定集合若在第一轮按语义显著性保留了大面积区域，第三轮的局部文字 token 可能已被剪掉；熵引导在第三轮重算预算，把注意力分散到该局部区域的 token 重新纳入 top-k。</li>\n</ul>\n<p>反过来，若负载是单轮 VQA 且图像 token 数中等，一次性剪枝的端到端延迟更低，因为熵引导的每轮重算在单轮里只发生一次却仍要付出注意力导出的实现成本，收益不足以抵消耦合度。这就是决策表里“轮次≥2 且漂移可观测”作为熵引导前置条件的原因。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-46\">四十六 · 与逐层压缩、双阶段缩减的对照：改长度还是改预算</h3>\n<p>逐层视觉 token 压缩在层间递减序列长度，压缩比随层深变化，其决策通常基于该层的注意力或特征相似度。双阶段统一 token 缩减则在视觉侧与语言侧各做一次缩减，形成两级预算。熵引导与二者的关键区别是：它不改变层间序列长度，压缩后的序列在整个解码过程中保持固定长度，变的只是“每轮重设的预算”。这意味着它的 KV cache 形状在单轮内是稳定的，而在轮间是变化的——这对连续批处理是友好的，因为同一批内各请求的序列长度不随层深抖动，只在轮边界跳变。</p>\n<p>代价上的对照很直接。逐层压缩的收益随层深累积，越往后序列越短，注意力计算量下降明显，但实现上要改每层的输入形状，与融合内核的适配成本高。双阶段缩减在视觉侧先砍一刀，语言侧再砍一刀，两次决策互相独立，可能出现视觉侧保留了语言侧不需要的 token。熵引导只做一次决策但做多次（每轮一次），实现上集中在注意力读取与排序，不改层间形状，因此与张量并行的适配更简单——剪枝发生在 LLM 内部，需与注意力算子同卡，但不跨层传播形状变化。</p>\n<table class=\"mini\"><thead><tr><th>对照维度</th><th>逐层压缩</th><th>双阶段缩减</th><th>熵引导</th></tr></thead><tbody><tr><td>序列长度变化位置</td><td>层间递减</td><td>视觉侧与语言侧各一次</td><td>轮边界跳变，层内固定</td></tr><tr><td>决策信号</td><td>层内注意力/特征相似度</td><td>两级独立打分</td><td>注意力分布熵 + 整流</td></tr><tr><td>KV cache 形状</td><td>随层深变化</td><td>两段式</td><td>单轮稳定、轮间变化</td></tr><tr><td>主要系统代价</td><td>内核形状适配</td><td>两级预算协调</td><td>每轮重算前向 + 注意力导出</td></tr></tbody></table>\n<p>一个具体判断：若服务以长文档图像、单轮为主，逐层压缩的累积收益更大，因为层间递减能把深层注意力成本压下来；若服务以多轮对话为主且每轮关注区域不同，熵引导的轮间预算重设更贴合负载，代价是每轮多一次前若干层前向。双阶段缩减适合视觉侧冗余极高、语言侧上下文极长的场景，但它不解决漂移，轮次一多仍需外部重打分。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-47\">四十七 · 与量化感知剪枝、近似误差引导压缩的对照：误差是否联合建模</h3>\n<p>量化感知视觉剪枝把量化误差纳入剪枝决策，近似误差引导压缩用近似误差作为保留准则。熵引导不联合量化误差，它只处理注意力未校准与漂移问题。这个分工决定了组合方式而非替代关系：在已经做 INT8 视觉分支、INT4 LLM 权重的部署里，熵引导的排序信号与量化误差是正交的，可以先按熵定保留集合，再让量化误差在保留集合内决定精度分配；反过来，若先按量化误差剪枝，熵引导就失去了对漂移的响应能力，因为被量化误差判为可删的 token 已经不在候选集里。</p>\n<p>代价上，联合建模的算法要多一次误差估计前向或统计量收集，熵引导则多一次注意力读取与熵计算。两者叠加时，额外前向开销相加，在长多轮会话里会挤压每轮增量延迟预算。因此部署配方上应避免在同一请求路径上串行两次全量打分：可以让熵引导在前若干层读注意力，量化误差估计复用同一批中间激活，减少重复前向。</p>\n<ul>\n<li>机制差异：量化感知剪枝的准则是量化后重构误差，熵引导的准则是注意力分布的不确定性，后者对注意力尺度不敏感、跨模型迁移性好。</li>\n<li>代价差异：熵引导的额外开销集中在注意力导出与每轮重算，量化感知剪枝的开销集中在误差统计，二者都随上下文长度增长。</li>\n<li>例子：细节密集型图像上，量化感知剪枝可能保留高误差敏感的边缘 token，熵引导则可能因这些 token 的注意力分布集中而判为低熵剪掉；两者结论冲突时，应以任务证据类型裁决——文字识别类任务偏向量化误差准则，语义问答类偏向熵准则。</li>\n</ul>\n<p>近似误差引导压缩与熵引导的冲突点在于“分散但不可替代”的 token。熵高表示证据分散、不可替代，近似误差准则可能认为这类 token 可被低秩近似替代。当图像含大量重复纹理时，两者结论一致；当图像含稀疏关键证据时，熵引导更保守，近似误差准则更激进。选择时应看下游任务是否对稀疏证据敏感。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-48\">四十八 · 决策表：按负载形态与栈能力选型</h3>\n<p>把上述对照收敛成一张可执行的决策表。表的行是负载形态，列是栈能力，单元格给出首选算法与必须满足的前置条件。读表的方式是先看栈是否导出注意力，再看轮次与证据粒度，最后看量化是否已在路径上。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>注意力可导出</th><th>注意力不可导出</th></tr></thead><tbody><tr><td>单轮 VQA，token 中等</td><td>一次性输入端剪枝优先，熵引导仅在漂移探针显示排序不稳时启用</td><td>一次性输入端剪枝或双阶段缩减，熵引导不可用</td></tr><tr><td>多轮对话，每轮关注区域变化</td><td>熵引导首选，前置条件为每轮预算重设与整流归一化</td><td>双阶段缩减 + 轮间外部重打分，接受额外打分前向</td></tr><tr><td>长文档图像，单轮为主</td><td>逐层压缩优先，熵引导作为层内补充</td><td>逐层压缩，需内核形状适配</td></tr><tr><td>细节密集型（OCR 级证据）</td><td>量化感知剪枝或近似误差引导压缩优先，熵引导仅作保守兜底</td><td>量化感知剪枝，避免纯熵排序</td></tr><tr><td>已量化路径（INT8 视觉 + INT4 LLM）</td><td>熵引导定保留集合，量化误差在集合内分配精度</td><td>量化感知剪枝单路径，不叠加熵</td></tr></tbody></table>\n<p>适用条件要写成可检验的判据，而不是倾向性描述。熵引导的启用条件至少包括三条：栈能在前若干层读取文本对视觉 token 的注意力，或具备等价的导出路径；会话轮次≥2 且漂移探针显示 top-k 交集低于阈值；每轮增量延迟预算能容纳一次前若干层的前向与熵计算。三条缺一，就应退到一次性剪枝或双阶段缩减。规模上限受第三条约束：轮次越多、上下文越长，重算熵的算力占比越高，未给出具体上限数字，工程上应以每轮增量延迟的实测占比作为扩容判据。</p>\n\n<h3 id=\"alg-era-entropy-prune-sec-49\">四十九 · 选型后的工程落点：预算、内核与回退</h3>\n<p>选定熵引导后，落点集中在三处。第一是预算的轮间传递：每轮重算熵得到的 top-k 集合要与上一轮做交集统计，交集骤降时触发整流强度上调，抑制注意力尺度差异带来的抖动。第二是内核耦合：若推理栈使用融合注意力内核且不暴露注意力矩阵，熵无法计算，需额外导出路径，吞吐下降且实现复杂；此时要么改用非融合内核的注意力读取分支，要么在融合内核上开一个只读的注意力摘要出口，代价是额外的显存带宽。第三是回退：top-k 预算按固定比例设置时，遇到细节密集型图像会剪掉过多 token，答案出现物体属性或文字识别错误，回退策略是按图像类型切换预算比例，或在检测到低熵 token 占比异常时临时放宽 top-k。</p>\n<div class=\"formula\">$$\\text{budget}_{r}=\\text{clip}\\left(\\alpha\\cdot\\text{topk}(H^{(r)}),\\ \\text{floor},\\ \\text{cap}\\right),\\quad \\text{floor}=f(\\text{task},\\text{image-type})$$</div>\n<p>这个预算式表达的是轮次 r 的保留数由该轮熵排序的 top-k 经任务与图像类型决定的上下界裁剪得到。floor 随任务变化：OCR 类任务抬高 floor，语义问答类任务可降低 floor 以换取吞吐。cap 防止单轮保留过多导致 KV cache 长度跳变过大，影响连续批处理的批内一致性。多轮历史过长使熵估计被旧轮次稀释时，应在计算熵之前对历史文本的注意力做截断或降权，否则本轮关键证据会被误判为低熵而剪除。</p>\n<p>最后一条工程判断：熵引导的价值不在单轮精度，而在多轮中把“当时的关键证据”留在序列里。因此它的选型不应与一次性剪枝比单轮延迟，而应与“双阶段缩减 + 轮间外部重打分”比总代价——后者每轮多一次完整打分前向，熵引导只多前若干层的前向与熵计算，在轮次多、上下文长的负载里前者更贵。当栈无法导出注意力时，这个比较不成立，应直接选双阶段缩减并接受外部重打分的开销，而不是强行在融合内核上开导出路径。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 视觉Token压缩与合并</td></tr><tr><td>解决什么</td><td>基于注意力的剪枝在跨模态注意力未校准时会误删高信息 token，尤其在多轮对话中注意力分布漂移，导致关键视觉证据丢失。</td></tr><tr><td>一句话机制</td><td>用视觉 token 在语言侧注意力分布的熵作为不确定性度量，熵高者保留，并对注意力做整流以稳定跨模态打分。</td></tr><tr><td>代价与失效</td><td>需在 LLM 内部读取注意力，与 FlashAttention 融合需额外导出；每轮重算熵带来额外前向开销</td></tr><tr><td>后继</td><td>逐层视觉 token 压缩</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-era-entropy-prune · 共 8 个片段</p>\n";break;}}})();
